    now = time.time()
    p.db.set_kv(coord.RETRY_WAKE_KEY, {"at": now + 3600, "review": False})
    assert "24 h cap on new tasks is full" in web.health(p, p.db, alive=True)["why_idle"]
    p.db.set_kv(coord.RETRY_WAKE_KEY, {"at": now + 3600, "review": True})
