def test_memory_never_claims_a_rejected_config_change(env):
    """A memory_add naming a setting whose config_set the same turn was rejected says in the entry that
    the change is not in effect (whatever the action order); one naming nothing rejected is kept as is."""
    from ttp import coordinator as coord
    p = make(env)
    probs = coord.apply(p, [
        {"type": "memory_add", "text": "Enabled allow_protected_push_branch: reviewed work lands on main now.",
         "title": "push to main on"},
        {"type": "config_set", "key": "delivery.allow_protected_push_branch", "value": True},
        {"type": "memory_add", "text": "The daily review runs at 09:00.", "title": "review time"}], turn=7)
    assert any("needs the user's approval" in x for x in probs), probs
    assert not p.config()["delivery"].get("allow_protected_push_branch")
    entries = {f.name: f.read_text() for f in p.memory_dir.glob("*.md")}
    on = next(t for n, t in entries.items() if "push-to-main-on" in n)
    assert "Not in effect: config_set delivery.allow_protected_push_branch was rejected" in on
    assert "setting is unchanged" in on
    other = next(t for n, t in entries.items() if "review-time" in n)
    assert "Not in effect" not in other
    # In a user turn the change goes through, and the memory stays as written.
    coord.apply(p, [{"type": "config_set", "key": "delivery.allow_protected_push_branch", "value": True},
                    {"type": "memory_add", "text": "delivery.allow_protected_push_branch is on, by the user's yes.",
                     "title": "user turned it on"}], user_turn=True, turn=8)
    assert p.config()["delivery"]["allow_protected_push_branch"] is True
    assert "Not in effect" not in next(f for f in p.memory_dir.glob("*user-turned-it-on*.md")).read_text()



def test_tasks_a_worker_handed_off_blocked_on_the_setting_join_its_hold_and_are_released_with_it(env):
    """A blocked task with no anchor whose hand-off names the held setting is anchored to the open ask
    and released with the rest: when the setting turns on, or when the ask is resolved."""
    from ttp import coordinator as coord
    from ttp import settinghold
    from ttp.daemon import Daemon
    from ttp.db import dump_result
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    ids = {n: p.db.add_task(f"Task {n}", "fix it", kind="code", tier="light", origin="user")
           for n in ("reason", "summary", "other", "anchored")}

    def block():
        p.db.update_task(ids["reason"], status="blocked",
                         blocked_reason="ttp push refused: delivery.allow_protected_push_branch is off")
        p.db.update_task(ids["summary"], status="blocked", blocked_reason="need the user's word",
                         result=dump_result({"status": "blocked",
                                             "summary": "Reviewed head abc; allow_protected_push_branch is off."}))
        p.db.update_task(ids["other"], status="blocked", blocked_reason="needs a credential")
        p.db.update_task(ids["anchored"], status="blocked", labels=json.dumps(["waits:until:9999999999"]),
                         blocked_reason="allow_protected_push_branch is off; waiting a day")
    block()
    d = Daemon(p.base)
    d.sweep_holds()   # no ask names it: nothing joins
    assert all("waits:ask" not in (p.db.task(t)["labels"] or "") for t in ids.values())
    for resolve_by in ("setting", "ask"):
        aid = _setting_ask(p)
        d.sweep_holds()
        for n in ("reason", "summary"):
            t = p.db.task(ids[n])
            assert t["status"] == "blocked" and f'"waits:ask:{aid}"' in t["labels"], t
            assert settinghold.held_key(t) and "Handed off:" in t["blocked_reason"], t
        assert "waits:" not in (p.db.task(ids["other"])["labels"] or "")
        assert "waits:until" in p.db.task(ids["anchored"])["labels"]
        lines = [ln for ln in coord.digest(p, {}, [], []).splitlines() if "setting hold" in ln]
        assert len(lines) == 1 and f"#{ids['reason']}, #{ids['summary']}" in lines[0], lines
        if resolve_by == "setting":
            p.set_config("delivery.allow_protected_push_branch", True)
            d.cfg = p.config()
        else:
            assert coord.apply(p, [{"type": "resolve", "id": aid}]) == []
        d.sweep_holds()
        for n in ("reason", "summary"):
            assert p.db.task(ids[n])["status"] == "queued", (resolve_by, p.db.task(ids[n]))
        assert p.db.task(ids["other"])["status"] == "blocked"
        why = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='hold_released'")]
        assert len(why) == (2 if resolve_by == "setting" else 4), why
        assert ("was turned on" if resolve_by == "setting" else "no open ask names") in why[-1], why
        p.set_config("delivery.allow_protected_push_branch", False)
        d.cfg = p.config()
        p.db.x("UPDATE messages SET handled=1 WHERE kind='ask'")
        block()



def test_probes_that_can_never_pass_are_flagged_once_per_wait(env, tmp_path):
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    assert coord.EFFORT_EVENT_TRIGGERS["probe_never_passes"] == "stuck"
    missing = _due_waiting_task(p, "no-such-command-xyz --check")
    _settle_probe(d, missing)
    ev = _never(p, missing)
    assert len(ev) == 1 and "not found (exit 127)" in ev[0]["text"] and ev[0]["status"] == "queued"
    assert "no-such-command-xyz" in ev[0]["text"] and f"set-when {missing}" in ev[0]["text"]
    gone = _due_waiting_task(p, f"test -e {p.runs}/99999/done")
    (p.runs / "88888").mkdir(parents=True, exist_ok=True)
    live = _due_waiting_task(p, f"test -e {p.runs}/88888/done")
    for t in (gone, live):
        _settle_probe(d, t)
        _reprobe(d, t)
    assert len(_never(p, gone)) == 1 and "99999" in _never(p, gone)[0]["text"]
    assert not _never(p, live), "a missing marker in a live run dir is the normal wait"
    unknown = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 1, 'j: unknown to the runner in /x')} devq probe r j")
    _settle_probe(d, unknown)
    assert len(_never(p, unknown)) == 1 and "unknown to its runner" in _never(p, unknown)[0]["text"]



def test_a_start_when_that_waits_for_hours_on_a_device_resource_raises_one_event(env):
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    assert coord.EFFORT_EVENT_TRIGGERS["start_resource_stale"] == "resource"
    old = time.time() - 4 * 3600
    dev = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                        labels=["start_when:false", f"deferred_since:{old}", "resource:device"])
    plain = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                          labels=["start_when:false", f"deferred_since:{old}", "resource:disk"])
    fresh = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                          labels=["start_when:false", f"deferred_since:{time.time()}", "exclusive:serving"])
    for _ in range(2):
        for t in (dev, plain, fresh):
            d._start_verdict(p.db.task(t), 1, time.time())
    ev = p.db.q("SELECT * FROM events WHERE kind='start_resource_stale'")
    assert [e["task"] for e in ev] == [dev] and "device" in ev[0]["text"] and "Blocking gate: false" in ev[0]["text"]
    d.cfg["waiting"]["start_resource_stale_s"] = 0
    d._start_verdict(p.db.task(fresh), 1, time.time() + 5 * 3600)
    assert len(p.db.q("SELECT * FROM events WHERE kind='start_resource_stale'")) == 1, "0 turns it off"



def test_a_false_start_when_shows_its_last_result_and_age_and_warns_only_past_the_threshold(env):
    """A deferred task's start_when gate shows its last result (exit code and the probe's last word),
    when it last ran and how long it has said not yet, in ttp status and the web app's task row. Past
    waiting.start_gate_warn_s it is a warning in the feed (a status row), never a 'needs you' item."""
    from ttp import startgate
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    from ttp.web import attention, state_payload
    p = make(env)
    d = Daemon(p.base)
    tid = p.db.add_task("bench", "s", kind="work", tier="light", origin="user",
                        labels=["start_when:test -e /nonexistent/marker", f"deferred_since:{time.time()}"])
    now = time.time()
    d._probe_out[tid] = ("waiting for the marker\n", now, "test -e /nonexistent/marker")
    d._start_verdict(p.db.task(tid), 1, now - 20 * 60)   # first false 20 min ago
    d._start_verdict(p.db.task(tid), 1, now - 2 * 60)    # last checked 2 min ago
    line = next(ln for ln in status_text(p).splitlines() if f"#{tid} deferred" in ln)
    assert "gate not yet (exit 1: waiting for the marker), checked 2 min ago, false for 20 min" in line, line
    assert "warning" not in line, "no warning before the threshold"
    row = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)
    assert row["gate"]["rc"] == 1 and not row["gate"]["warn"] and "false for 20 min" in row["gate"]["text"]
    assert not [m for m in state_payload(p, p.db)["feed"] if m["kind"] == "gate"]
    # Past the threshold (first false 40 min ago): a warning, in the feed as a status row.
    gates = p.db.kv(startgate.KEY)
    gates[str(tid)]["since"], gates[str(tid)]["run_s"] = now - 40 * 60, 38 * 60   # the daemon ran throughout
    p.db.set_kv(startgate.KEY, gates)
    line = next(ln for ln in status_text(p).splitlines() if f"#{tid} deferred" in ln)
    assert "false for 40 min; warning: still false after 30 min" in line, line
    pay = state_payload(p, p.db)
    assert next(t for t in pay["tasks"] if t["id"] == tid)["gate"]["warn"]
    rows = [m for m in pay["feed"] if m["kind"] == "gate"]
    assert len(rows) == 1 and rows[0]["state"] == "status" and f"#{tid} bench waits to start" in rows[0]["text"]
    assert not attention(p.db, time.time()), "a stale gate never needs the user"
    assert "needs you" not in status_text(p)
    # A higher threshold (or 0) takes the warning off; a pass forgets the gate.
    p.set_config("waiting.start_gate_warn_s", 3600)
    assert "warning" not in next(ln for ln in status_text(p).splitlines() if f"#{tid} deferred" in ln)
    d._start_verdict(p.db.task(tid), 0, now)
    assert str(tid) not in (p.db.kv(startgate.KEY) or {})


def test_a_landed_start_gate_names_its_producers_state(env):
    """A landed:#<id> gate that says not yet names the producer's state, e.g. 'producer #N in review';
    the first-false time survives later verdicts and resets once the probe is re-pointed."""
    from ttp import startgate
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    prod = p.db.add_task("producer", "s", kind="code", origin="user")
    p.db.update_task(prod, status="review")
    tid = p.db.add_task("consumer", "s", kind="work", tier="light", origin="user",
                        labels=[f"start_when:landed:#{prod}", f"deferred_since:{time.time()}"])
    now = time.time()
    d._start_verdict(p.db.task(tid), 1, now - 600)
    p.db.update_task(prod, status="pushing")
    d._start_verdict(p.db.task(tid), 1, now - 60)
    g = p.db.kv(startgate.KEY)[str(tid)]
    assert g["reason"] == f"producer #{prod} being pushed" and g["since"] == now - 600 and g["at"] == now - 60
    p.db.update_task(prod, status="review")
    assert startgate.reason(p.db, f"landed:#{prod}", 1) == f"producer #{prod} in review"
    assert startgate.reason(p.db, f"ttp landed --task {prod}", 1) == f"producer #{prod} in review"
    line = next(ln for ln in status_text(p).splitlines() if f"#{tid} deferred" in ln)
    assert f"starts when #{prod} lands" in line and f"producer #{prod} being pushed" in line, line
    # Re-pointed: the old verdict is not credited to the new probe.
    p.db.update_task(tid, labels=["start_when:false", f"deferred_since:{time.time()}"])
    d._drop_stale_probe(tid, "false")
    assert str(tid) not in (p.db.kv(startgate.KEY) or {})


def test_a_start_gate_warns_on_daemon_running_time_not_wall_time(env):
    """The stale-gate warning counts only time the daemon ran: a host down for 40 h between two
    verdicts adds at most startgate.GAP_S, so a gate set before the outage is not called stale
    on the daemon's first verdicts back; it warns once 30 min of daemon time have passed."""
    from ttp import startgate
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    tid = p.db.add_task("bench", "s", kind="work", tier="light", origin="user",
                        labels=["start_when:test -e /nonexistent/marker", f"deferred_since:{time.time()}"])
    now = time.time()
    d._start_verdict(p.db.task(tid), 1, now - 40 * 3600 - 300)   # set, then the host went down
    d._start_verdict(p.db.task(tid), 1, now - 120)               # back up
    v = startgate.view(p.db, p.db.task(tid), now, 1800)
    assert not v["warn"] and "warning" not in v["text"], v
    assert "false for 40.1 h (17 min of it with the daemon running)" in v["text"], v["text"]
    assert not startgate.feed(p.db, 1800, now)
    for k in range(1, 6):   # the daemon keeps running: 3-min verdicts until 32 min of daemon time
        d._start_verdict(p.db.task(tid), 1, now - 120 + k * 180)
    later = now - 120 + 5 * 180
    v = startgate.view(p.db, p.db.task(tid), later, 1800)
    assert v["warn"] and "warning: still false after 30 min of daemon time" in v["text"], v["text"]
    assert len(startgate.feed(p.db, 1800, later)) == 1


def _stale_landed_gate(p, prod):
    """A consumer deferred on landed:#<prod> whose gate has said not yet for 40 min of daemon time."""
    from ttp import startgate
    from ttp.daemon import Daemon
    tid = p.db.add_task("consumer", "s", kind="work", tier="light", origin="user",
                        labels=[f"start_when:landed:#{prod}", f"deferred_since:{time.time()}"])
    d, now = Daemon(p.base), time.time()
    for k in range(15):
        d._start_verdict(p.db.task(tid), 1, now - 42 * 60 + k * 180)
    return tid, now


def test_a_landed_start_gate_names_the_push_queue_instead_of_warning(env):
    """While the producer's change (its review's approval) is approved or batched in the push queue,
    a long-false landed:#<id> gate names the queue state, not a staleness warning, and has no feed row."""
    from ttp import startgate
    from ttp.cli import status_text
    p = make(env)
    prod = p.db.add_task("producer", "s", kind="code", origin="user")
    p.db.update_task(prod, status="done")
    rev = p.db.add_task(f"Review #{prod}", "s", kind="review", origin="daemon", labels=[f"auto_review:{prod}"])
    p.db.update_task(rev, status="pushing")
    tid, now = _stale_landed_gate(p, prod)
    row = p.db.x("INSERT INTO push_queue(task,branch,head,target,status,created,updated) "
                 "VALUES(?,?,?,?,'approved',?,?)", (rev, "ttp/t1", "abc123", "origin/main", now, now))
    v = startgate.view(p.db, p.db.task(tid), now, 1800)
    assert not v["warn"] and v["text"].endswith("; approved, waiting on the next push batch"), v["text"]
    p.db.x("UPDATE push_queue SET status='batched', batch='b20261019' WHERE id=?", (row,))
    v = startgate.view(p.db, p.db.task(tid), now, 1800)
    assert not v["warn"] and v["text"].endswith("; waiting on push batch b20261019"), v["text"]
    assert "warning" not in v["text"] and not startgate.feed(p.db, 1800, now)
    line = next(ln for ln in status_text(p).splitlines() if f"#{tid} deferred" in ln)
    assert "waiting on push batch b20261019" in line and "warning" not in line, line
    # Pushed and settled but still not on the branch: the warning is back.
    p.db.x("UPDATE push_queue SET status='pushed' WHERE id=?", (row,))
    assert startgate.view(p.db, p.db.task(tid), now, 1800)["warn"]


@pytest.mark.parametrize("state", ["failed", "cancelled", "done"])
def test_a_landed_start_gate_still_warns_for_a_producer_out_of_the_push_queue(env, state):
    """A producer that failed, was cancelled or is done with no push queue entry keeps the warning."""
