# Health evidence ends coordinator pauses, fenced against a changed pause.
HEALTH_END = {"heal": "svc", "healthy_n": 3, "clean_s": 1800}   # the end health_end() gives check `svc`



def _health_pause(env, *, shared=False, by="coordinator", every_s=900, end=None):
    from ttp import coordinator as coord
    p, d, up = _heal_setup(env, resource="board")
    p.db.x("UPDATE schedules SET every_s=? WHERE name='svc'", (every_s,))   # results stay fresh 2 * every_s
    up.touch()
    if shared:
        p.set_config("shared_resources", ["board"])
    if by == "user":
        coord.pause_resource(p, "board", True, by="user", end={"end_when": dict(HEALTH_END)})
    else:   # the coordinator's pause of a heal-checked resource gets the health end by itself
        assert coord.apply(p, [{"type": "resource_pause", "resource": "board", "paused": True, **(end or {})}]) == []
    return p, d, up



@pytest.mark.parametrize("end", [dict(HEALTH_END), {"heal": "svc"}, {"heal": "svc", "healthy_n": 1, "clean_s": 0},
                                 {}, ["true"], 1])
def test_resource_pause_end_when_is_only_a_probe(env, end):
    # Nobody writes or tunes a health end: an object (or other non-string) end is refused, never applied.
    from ttp import coordinator as coord, pauseends
    p, d, _ = _health_pause(env)
    coord.pause_resource(p, "board", False)
    problems = coord.apply(p, [{"type": "resource_pause", "resource": "board", "paused": True, "until": "1d",
                                "end_when": end}])
    assert problems and "one shell command" in problems[0], problems
    assert "board" not in p.db.paused_resources()
    with pytest.raises(ValueError, match="one shell command"):
        pauseends.from_action({"until": "1d", "end_when": end})



@pytest.mark.parametrize("given", [True, False])
def test_resource_pause_end_fields_ride_the_strict_wire_schema(env, given):
    # A strict provider sends only the keys the wire schema lists and pads the rest with null: the
    # coordinator's probe and report_from must reach apply(), and their padding must read as absent.
    from ttp import coordinator as coord
    from ttp.providers.base import strict_schema
    p = make(env)
    wire = strict_schema(coord.ACTIONS_SCHEMA)
    item = wire["properties"]["actions"]["items"]
    assert item["additionalProperties"] is False
    assert all(item["properties"][k]["type"] == ["string", "null"] for k in ("end_when", "report_from"))
    action = dict.fromkeys(item["properties"])
    action.update(type="resource_pause", resource="board", paused=True, until="1d",
                  **({"end_when": "test -e done", "report_from": "other"} if given else {}))
    try:
        import jsonschema
    except ImportError:
        jsonschema = None
    if jsonschema:
        jsonschema.validate({"actions": [action], "summary": None}, wire)
    assert coord.apply(p, [action]) == []
    held = p.db.paused_resources()["board"]
    assert (held.get("end_when"), held.get("report_from")) == (("test -e done", "other") if given else (None, None))
    assert 86400 - 60 < held["until"] - time.time() <= 86400



@pytest.mark.parametrize("words,context,flag,users", [
    ("Pause board until I explicitly allow it again.", None, False, True),
    ("Take it offline for now, please.", None, True, True),   # the coordinator marks the user's own ask
    ("How is the build going?", None, False, False),           # unrelated words
    ("How is the build going?", "They said to pause board.", False, False),   # a relayer's context only
])
def test_resource_pause_origin_follows_the_users_own_words(env, words, context, flag, users):
    from ttp import coordinator as coord
    p, d, _ = _health_pause(env)
    coord.pause_resource(p, "board", False)
    msg = p.db.post("in", words)
    if context:
        p.db.x("UPDATE messages SET context=? WHERE id=?", (context, msg))
    action = {"type": "resource_pause", "resource": "board", "paused": True, **({"user_asked": True} if flag else {})}
    assert coord.apply(p, [action], user_turn=True, messages=[msg]) == []
    assert p.db.paused_resources()["board"]["by"] == ("user" if users else "coordinator")
    # Without a user message in the turn, neither the words nor the flag make it theirs.
    coord.pause_resource(p, "board", False)
    assert coord.apply(p, [{**action, "user_asked": True}]) == []
    assert p.db.paused_resources()["board"]["by"] == "coordinator"



@pytest.mark.parametrize("flag,users", [(None, True), (False, False), (True, True)])
def test_resource_pause_in_a_turn_asking_to_pause_fails_safe_to_the_user(env, flag, users):
    from ttp import coordinator as coord
    p, d, _ = _health_pause(env)
    coord.pause_resource(p, "board", False)
    msg = p.db.post("in", "Pause the other box please.")
    action = {"type": "resource_pause", "resource": "board", "paused": True, "until": "1d",
              **({} if flag is None else {"user_asked": flag})}
    assert coord.apply(p, [action], user_turn=True, messages=[msg]) == []
    # Unflagged, words that ask to pause make it theirs; only an explicit `user_asked: false` keeps it ours.
    assert p.db.paused_resources()["board"]["by"] == ("user" if users else "coordinator")



def test_a_task_reference_to_a_missing_task_is_rejected_and_reaches_the_coordinator(env, monkeypatch):
    """start_when landed:#<id>, a `ttp landed --task <id>` probe, a hold's when probe and depends_on that
    name no task in this project are refused per action, and the refusal reaches the next digest."""
    from types import SimpleNamespace
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    p.set_config("delivery.push_branch", "work")   # landed:#<id> is checkable here
    ok = p.db.add_task("the change", "s", origin="user")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    before = p.db.one("SELECT COUNT(*) n FROM tasks")["n"]
    cases = [({"start_when": "landed:#0"}, "start_when landed:#0 names no task in this project"),
             ({"start_when": "landed:#987654"}, "names no task in this project (no task #987654)"),
             ({"start_when": "ttp landed --task 0 && test -f x"}, "(no task #0)"),
             ({"start_when": "ttp landed --task=abc"}, "(no task #abc)"),
             ({"depends_on": [0]}, "depends_on #0 names no task in this project"),
             ({"depends_on": [-3]}, "depends_on #-3 names no task in this project"),
             ({"depends_on": [987654]}, "no task #987654")]
    for extra, why in cases:
        problems = coord.apply(p, [{"type": "task_add", "title": "after it", "spec": "s", **extra},
                                   {"type": "task_add", "title": f"fine {why}", "spec": "s"}])
        assert len(problems) == 1 and problems[0].startswith('task_add: "after it": ') and why in problems[0], \
            (extra, problems)
        assert "use an existing task id or drop" in problems[0], problems
    assert not p.db.q("SELECT id FROM tasks WHERE title='after it'"), "a rejected task_add created a task"
    assert p.db.one("SELECT COUNT(*) n FROM tasks")["n"] == before + len(cases), "the rest of the batch was lost"
    for bad in ("landed:#-1", "landed:#x"):   # not a task id at all: the format check refuses it
        assert coord.apply(p, [{"type": "task_add", "title": "after it", "spec": "s", "start_when": bad}])
    # task_update: a re-deferral, a hold's when probe and depends_on.
    tid = p.db.add_task("later", "s", origin="user")
    for upd, why in (({"start_when": "landed:#0"}, f"#{tid} rejected: start_when landed:#0 names no task"),
                     ({"status": "blocked", "waits_on": "when:landed:#424242"}, "(no task #424242)"),
                     ({"depends_on": [0]}, "names no task in this project")):
        problems = coord.apply(p, [{"type": "task_update", "id": tid, "priority": 1, **upd}])
        assert len(problems) == 1 and why in problems[0], (upd, problems)
        assert p.db.task(tid)["priority"] == 3 and p.db.task(tid)["status"] == "queued", "a rejected update was applied"
    # An existing id still passes, in both forms.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": f"landed:#{ok}", "depends_on": [ok]}]) == []
    assert coord.apply(p, [{"type": "task_add", "title": "waits ok", "spec": "s", "start_when": f"landed:#{ok}",
                            "depends_on": [ok]}]) == []
    assert coord.starts_text(p.db.task(tid), plain=True, db=p.db) == f"starts when #{ok} lands"
    # The refusal comes back to the coordinator in its next digest.
    d = Daemon(p.base)
    d.update_gates()
    bad = SimpleNamespace(structured={"actions": [{"type": "task_add", "title": "ghost wait", "spec": "s",
                                                   "start_when": "landed:#0"}], "summary": ""},
                          error="", final_text="")
    d._finish_coordinator({"dir": "x"}, bad, "ok", {})
    digest = coord.digest(p, {}, [], [])
    assert 'task_add: "ghost wait": start_when landed:#0 names no task in this project' in digest, digest
    # The CLI's paths take the same check.
    from ttp.cli import set_when
    with pytest.raises(ValueError, match="names no task in this project"):
        set_when(p.db, tid, "landed:#0", p)
    waiting = p.db.add_task("waiting one", "s", origin="user", result=None)
    p.db.update_task(waiting, result=json.dumps({"status": "waiting", "retry_when": "true"}))
    with pytest.raises(ValueError, match=r"retry_when ttp landed --task 0 names no task"):
        set_when(p.db, waiting, "ttp landed --task 0", p)
    assert "ttp landed --task" in set_when(p.db, waiting, f"ttp landed --task {ok}", p)



def test_snapshot_memory_edits_and_retirements_stay_live_during_batching(env):
    from ttp import coordinator as coord
    p = make(env)
    start = time.time()
    fact = p.add_memory('Old build host.', kind='resource')
    before = coord.system_prompt(p, now=start)
    fact.write_text(fact.read_text().replace('Old build host.', 'New build host.'))
    view = coord.memory_view(p, now=start + 1)
    assert coord.system_prompt(p, now=start + 1) == before
    assert 'New build host.' in '\n'.join(coord.memory_digest_lines(view))
    p.forget_memory(fact.stem)
    view = coord.memory_view(p, now=start + 2)
    assert coord.system_prompt(p, now=start + 2) == before
    assert view['retired'] == [fact.stem]
    rule = p.add_memory('Never change shared branches.', kind='restriction')
    coord.system_prompt(p, now=start + 3)
    rule.write_text(rule.read_text().replace('shared branches.', 'shared state.'))
    assert 'Never change shared state.' in coord.system_prompt(p, now=start + 4)



def test_start_after_accepts_a_space_and_the_home_zone_abbreviation(env):
    from datetime import datetime, timezone
    from ttp import coordinator
    tz, now = "America/Los_Angeles", datetime(2026, 10, 13, 12, 0, tzinfo=timezone.utc).timestamp()
    want = datetime(2026, 10, 13, 23, 0, tzinfo=timezone.utc).timestamp()
    assert coordinator.parse_start_after("2026-10-13 16:00 PDT", now=now, tz=tz) == want
    assert coordinator.parse_start_after("2026-10-13 16:00", now=now, tz=tz) == want
    assert coordinator.parse_start_after("2026-12-01 16:00 pst", now=now, tz=tz) == \
        datetime(2026, 12, 2, 0, 0, tzinfo=timezone.utc).timestamp()
    with pytest.raises(ValueError, match=r"2026-10-13T16:00-07:00"):
        coordinator.parse_start_after("2026-10-13 16:00 EDT", now=now, tz=tz)
    with pytest.raises(ValueError, match=r"2026-10-13T16:00-07:00"):
        coordinator.parse_start_after("2026-10-13 16:00 PST", now=now, tz=tz)



def test_a_passing_review_marks_the_reviewed_head_for_the_tasks_that_continue_it(env, tmp_path, monkeypatch):
    from ttp import coordinator as coord, verified
    from ttp.daemon import Daemon
    p, repo, run, git, counts = _verified_checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.setattr(p, "root", repo)
    d = Daemon(p.base)
    d.p = p
    code = p.db.add_task("first hop", kind="code")
    review = p.db.add_task(f"Review #{code}: first hop", kind="review", depends_on=[code],
                           labels=[f"auto_review:{code}"])
    reviewed = _commit_in(git, repo, "src/a.py", "a = 1\n")
    extra = {}
    d._mark_verified(p.db.task(review), {"entries": [{"branch": "b", "head": reviewed}]}, extra)
    assert extra["verified_through"] == reviewed
    assert verified.own(p.db, code, "review") == {**verified.own(p.db, code, "review"), "sha": reviewed,
                                                   "review": review, "kind": "review"}
    # A fix that continues the review inherits the reviewed head: its review covers only what came after.
    fix = p.db.add_task("fix", kind="code", labels=[f"continues:{review}"])
    head = _commit_in(git, repo, "src/b.py", "b = 1\n")
    line = d._verified_review_line(p.db.task(fix), head)
    assert f"verified through {reviewed[:12]} (#{code}'s review)" in line
    assert f"git log {reviewed[:12]}..{head[:12]}" in line and "push checks still run in full" in line
    # Rewritten: the review covers the whole change.
    subprocess.run([*git, "reset", "-q", "--hard", "HEAD~2"], check=True)
    head = _commit_in(git, repo, "src/c.py", "c = 1\n")
    assert "review the whole change" in d._verified_review_line(p.db.task(fix), head)
    # A code task with no lineage has no marker line; the hand-off line shows the marker.
    assert d._verified_review_line(p.db.task(code), head) == ""
    p.db.update_task(review, status="done", result=json.dumps({"summary": "passed", **extra}))
    assert f"verified through {reviewed[:12]}" in coord.digest(p, {}, [], []).split("## Recently finished")[1]



def test_a_plain_task_done_waits_for_company_even_with_an_idle_slot(env):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p.db.x("UPDATE events SET status='handled'")
    p.db.x("UPDATE tasks SET status='done'")
    p.set_config("budget.max_parallel_workers", 2)
    d = Daemon(p.base)
    d.gates = {}
    now = time.time()
    done = p.db.add_task("finished", "s", status="done")
    ev = {"ts": now - 10, "kind": "task_done", "severity": "normal", "task": done}
    assert d._batch_hold([ev], now), "a plain hand-off with idle slots and no queued work waits for batch_s"
    assert not d._batch_hold([ev], now + 400), "batch_s still bounds the wait"
    assert not d._batch_hold([dict(ev, severity="high")], now)
    assert not d._batch_hold([dict(ev, task=None)], now)
    # A proposed follow-up is work the turn could queue into the idle slot.
    fid = p.db.x("INSERT INTO events(ts,source,kind,severity,text,status,task) VALUES(?,?,?,?,?,?,?)",
                 (now, f"task:{done}", "followup_proposed", "normal", "f", "queued", done))
    assert not d._batch_hold([ev], now)
    p.db.x("UPDATE events SET status='handled' WHERE id=?", (fid,))
    assert d._batch_hold([ev], now)
    # A live task depending on it, or a waiting parent, may need the turn now.
    dep = p.db.add_task("next", "s", status="waiting")
    p.db.x("UPDATE tasks SET depends_on=? WHERE id=?", (json.dumps([done]), dep))
    assert not d._batch_hold([ev], now)
    p.db.update_task(dep, status="done")
    assert d._batch_hold([ev], now)
    parent = p.db.add_task("parent", "s", status="waiting")
    p.db.x("UPDATE tasks SET parent=? WHERE id=?", (parent, done))
    assert not d._batch_hold([ev], now)
    p.db.update_task(parent, status="done")
    assert d._batch_hold([ev], now)
    # Normal upstream notes and info observations batch; they do not take the idle-slot hold.
    assert coord.batchable("upstream_note", "normal") and coord.batchable("observation", "info")
    assert not coord.batchable("upstream_note", "high") and not coord.batchable("task_done", "info")
    note = {"ts": now - 10, "kind": "upstream_note", "severity": "normal", "task": None}
    assert not d._batch_hold([ev, note], now)



def test_blocker_sweep_carries_a_valid_not_yet_due_still_blocked_forward_until_the_item_changes(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    a, b = db.add_task("waits on a repair"), db.add_task("no outcome yet")
    for t in (a, b):
        db.update_task(t, status="blocked", blocked_reason="r")
    sweep.start(db, cfg, "every 6h", now - 7 * 3600)
    db.x("UPDATE events SET status='handled'")
    assert coord.apply(p, [{"type": "sweep", "id": a, "outcome": "still_blocked", "until_probe": "test -e /x",
                            "start_after": "2d"}]) == []
    eid = sweep.start(db, cfg, "every 6h", now)
    state = db.kv(sweep.STATE_KEY)
    assert state["carried"] == [f"task:{a}"] and f"task:{a}" not in state["flags"]
    assert "1 carried forward" in db.one("SELECT text FROM events WHERE id=?", (eid,))["text"]
    assert "CARRIED (no action)" in coord.digest(p, {}, [eid], [])
    text = "\n".join(sweep.digest_lines(db, [eid], now))
    [line_a] = [ln for ln in text.splitlines() if ln.startswith(f"- #{a} ")]
    assert "CARRIED (no action)" in line_a and "until test -e /x" in line_a and "FLAG" not in line_a
    assert "CARRIED" not in next(ln for ln in text.splitlines() if ln.startswith(f"- #{b} "))
    # The header names the start_after format and both required still_blocked fields.
    assert "1 CARRIED" in text and "per item not marked CARRIED" in text
    assert "both required" in text and "AND `start_after`" in text and "2026-10-05T09:00" in text
    # The next sweep carries it again, without a flag for "no outcome at the last sweep".
    db.x("UPDATE events SET status='handled'")
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    assert db.kv(sweep.STATE_KEY)["carried"] == [f"task:{a}"]
    assert f"task:{a}" not in db.kv(sweep.STATE_KEY)["flags"]
    # An interval sweep where every item is carried is skipped.
    db.update_task(b, status="done")
    db.x("UPDATE events SET status='handled'")
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # A changed item (new reason) needs a fresh outcome.
    db.update_task(a, blocked_reason="a different reason")
    assert sweep.due(db, cfg, now + 14 * 3600) == "every 6h"
    sweep.start(db, cfg, "every 6h", now + 14 * 3600)
    assert db.kv(sweep.STATE_KEY)["carried"] == []
    assert db.kv(sweep.STATE_KEY)["flags"] == {f"task:{a}": "no outcome at the last sweep"}



def test_blocker_sweep_interval_with_every_item_carried_still_starts_on_a_pending_signal(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    a = db.add_task("waits on a repair")
    db.update_task(a, status="blocked", blocked_reason="r")
    sweep.start(db, cfg, "every 6h", now)
    db.x("UPDATE events SET status='handled'")
    assert coord.apply(p, [{"type": "sweep", "id": a, "outcome": "still_blocked", "until_probe": "test -e /x",
                            "start_after": "2d"}]) == []
    assert sweep.due(db, cfg, now + 7 * 3600) is None
    db.set_kv(sweep.SIGNAL_KEY, [{"ts": now + 3600, "why": "ask #5 resolved"}])
    assert sweep.due(db, cfg, now + 3 * 3600) == "ask #5 resolved"
    assert sweep.due(db, cfg, now + 7 * 3600) == "ask #5 resolved"
    eid = sweep.start(db, cfg, "every 6h", now)
    db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    sweep.prepare(db, eid, cfg, now)
    assert "for each item not marked CARRIED" in db.one("SELECT text FROM events WHERE id=?", (eid,))["text"]



def test_blocker_sweep_carries_user_pause_holds_without_an_outcome_and_starts_no_sweep_for_them(env):
    """A hold only the user's word lifts (a probe that only tests for a `user-*` marker) needs no sweep
    outcome, starts no sweep, raises no flag or loop, and stays listed for the user."""
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    probe = "test -e state/user-resume-tuning || exit 1"
    blocked = db.add_task("blocked on the user")
    db.update_task(blocked, status="blocked", blocked_reason="paused by the user", labels=[f"waits:when:{probe}"])
    for ts in (now - 7200, now - 3600):     # the same stuck reason twice: a loop for any other hold
        _sweep_ev(db, blocked, "task_blocked", f"#{blocked} blocked on the user: paused by the user", ts)
    waiting = db.add_task("waits on the user")
    db.update_task(waiting, status="waiting", result=json.dumps(
        {"status": "waiting", "summary": "paused", "retry_when": "test -f state/user-go"}))
    deferred = db.add_task("starts on the user's word", labels=[f"start_when:[ -e state/user-start ]",
                                                                 f"deferred_since:{now - 600}"])
    live = {i["key"]: i for i in sweep.items(db, now, cfg)}
    assert {k: (i["kind"], i["ends"]) for k, i in live.items()} == {
        f"task:{t}": ("user-pause", "user") for t in (blocked, waiting, deferred)}
    assert "held by user pause until `test -e state/user-resume-tuning || exit 1`" in live[f"task:{blocked}"]["reason"]
    assert sweep.due(db, cfg, now) is None, "only user pauses are stuck: no sweep turn"
    assert all(sweep.loop(db, i, None) is None for i in live.values())
    # Another stuck item starts a sweep: the user pauses are carried and listed, with no action asked.
    other = db.add_task("needs a key")
    db.update_task(other, status="blocked", blocked_reason="needs the vendor's key")
    assert sweep.due(db, cfg, now) == "every 6h"
    eid = sweep.start(db, cfg, "every 6h", now)
    state = db.kv(sweep.STATE_KEY)
    assert sorted(state["carried"]) == sorted(f"task:{t}" for t in (blocked, waiting, deferred))
    assert not state["loops"] and not state["flags"]
    text = coord.digest(p, {}, [eid], [])
    for t in (blocked, waiting, deferred):
        line = next(ln for ln in text.splitlines() if ln.startswith(f"- #{t} "))
        assert "HELD BY USER PAUSE (no action)" in line, line
    assert "3 CARRIED" in text
    # The next sweep flags only the item left without an outcome.
    db.x("UPDATE events SET status='handled'")
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    assert db.kv(sweep.STATE_KEY)["flags"] == {f"task:{other}": "no outcome at the last sweep"}
    # Once the other item is resolved, an interval sweep is skipped again.
    db.update_task(other, status="done")
    db.x("UPDATE events SET status='handled'")
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # The daily review still lists the user's pauses.
    rows = sweep.review_lines(db, now + 14 * 3600, where=p)
    assert any(f"#{blocked} " in r and "user-pause" in r and "none needed (ends by user)" in r for r in rows), rows



def test_blocker_sweep_leaves_out_planned_deferrals(env):
    """A queued task whose `start_after` is ahead is planned, not stuck: no item, no sweep, one count line.
    Past `start_after` with a probe it counts from start_after; a probe-only deferral counts as before."""
    p = make(env)
    from ttp import sweep
    db, cfg, now = p.db, p.config(), time.time()
    later = db.add_task("after the window", labels=[f"start_after:{now + 86400}", f"deferred_since:{now - 600}",
                                                    "start_why:after the window"])
    db.update_task(later, not_before=now + 86400)
    assert sweep.items(db, now, cfg) == []
    assert sweep.planned_deferrals(db, now) == 1
    assert sweep.due(db, cfg, now + 7 * 3600) is None
    assert sweep.review_lines(db, now, where=p) == ["nothing stuck longer than 6h", "planned deferrals: 1"]
    # Past start_after, still on a probe: aged from start_after, not from deferred_since.
    both = db.add_task("past", labels=[f"start_after:{now - 3600}", f"deferred_since:{now - 90000}",
                                       "start_when:test -e out/done"])
    probe_only = db.add_task("probe only", labels=["start_when:test -e out/done", f"deferred_since:{now - 7200}"])
    by = {i["task"]: i for i in sweep.items(db, now, cfg)}
    assert set(by) == {both, probe_only}
    assert 3500 < by[both]["age_s"] < 3700 and 7100 < by[probe_only]["age_s"] < 7300
    assert sweep.planned_deferrals(db, now) == 1


def test_blocker_sweep_carries_a_user_set_resource_pause_and_still_sweeps_a_coordinator_pause(env):
    """A resource pause the user set is lifted on their word only: listed, carried without an outcome
    and no reason for a sweep. A pause the coordinator set itself still needs an outcome."""
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    coord.pause_resource(p, "board-a", True, reason="hold for the user", by="user")
    live = {i["key"]: i for i in sweep.items(db, now, cfg)}
    assert (live["resource:board-a"]["kind"], live["resource:board-a"]["ends"]) == ("paused", "user")
    assert sweep.due(db, cfg, now) is None, "only a user-set pause: no sweep turn"
    assert sweep.loop(db, live["resource:board-a"], None) is None
    coord.pause_resource(p, "board-b", True, reason="flaky fabric", by="coordinator")
    live = {i["key"]: i for i in sweep.items(db, now, cfg)}
    assert live["resource:board-b"]["ends"] is None
    assert sweep.due(db, cfg, now) == "every 6h"
    eid = sweep.start(db, cfg, "every 6h", now)
    assert db.kv(sweep.STATE_KEY)["carried"] == ["resource:board-a"]
    text = coord.digest(p, {}, [eid], [])
    assert next(ln for ln in text.splitlines() if ln.startswith("- resource board-a ")).startswith(
        "- resource board-a | HELD BY USER PAUSE (no action): by user: hold for the user")
    assert "no action" not in next(ln for ln in text.splitlines() if ln.startswith("- resource board-b "))
    db.x("UPDATE events SET status='handled'")
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    assert db.kv(sweep.STATE_KEY)["flags"] == {"resource:board-b": "no outcome at the last sweep"}
    assert "board-a" in db.paused_resources(), "the sweep never lifts the user's pause"



def _board_work(p, now, n=2):
    """A user-set pause on board-a and `n` deferred tasks that name it (dispatch holds them on it)."""
    from ttp import coordinator as coord
    coord.pause_resource(p, "board-a", True, reason="hold for the user", by="user")
    return [p.db.add_task(f"bench {k} on board-a", labels=["resource:board-a", "start_when:test -e out/board-ready",
                                                           f"deferred_since:{now - 600}"]) for k in range(1, n + 1)]


def _set_pause_row(db, name, row):
    from ttp.db import PAUSED_RESOURCES_KEY
    rows = dict(db.kv(PAUSED_RESOURCES_KEY, {}) or {})
    if row is None:
        rows.pop(name, None)
    else:
        rows[name] = row
    db.set_kv(PAUSED_RESOURCES_KEY, rows)


def test_blocker_sweep_human_indispensable_on_a_user_paused_resource_carries_every_item_naming_it(env):
    """Once a sweep records human_indispensable for an item a user-set resource pause holds, the outcome
    keeps the pause row's fingerprint and every stuck task naming that resource ends with the user:
    carried, not re-judged, until a user message, a change of the pause row or its lift."""
    from ttp import coordinator as coord, sweep
    from ttp.db import PAUSED_RESOURCES_KEY
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    a, b = _board_work(p, now)
    assert {i["key"]: i["ends"] for i in sweep.items(db, now, cfg)} == {
        f"task:{a}": None, f"task:{b}": None, "resource:board-a": "user"}
    eid = sweep.start(db, cfg, sweep.due(db, cfg, now), now)
    db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    assert coord.apply(p, [{"type": "sweep", "id": a, "outcome": "human_indispensable",
                            "why": "only the user lifts the board-a pause"}]) == []
    row = db.kv(PAUSED_RESOURCES_KEY)["board-a"]
    assert db.kv(sweep.OUTCOMES_KEY)[f"task:{a}"]["pause"] == {"board-a": sweep._pause_fp(row)}
    live = {i["key"]: i for i in sweep.items(db, now + 60, cfg)}
    for t in (a, b):
        assert live[f"task:{t}"]["ends"] == "user", live[f"task:{t}"]
        assert live[f"task:{t}"]["reason"].startswith("held by user pause on board-a")
    # The next sweep carries both without an outcome, and none is due while nothing changes.
    eid = sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    state = db.kv(sweep.STATE_KEY)
    assert not state["flags"] and {f"task:{a}", f"task:{b}"} <= set(state["carried"])
    text = coord.digest(p, {}, [eid], [])
    assert "HELD BY USER PAUSE (no action): held by user pause on board-a" in next(
        ln for ln in text.splitlines() if ln.startswith(f"- #{b} "))
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # A user message ends the cover: the items are judged again.
    mid = db.post("in", "board-a: try the other cable", chat="c1", kind="user")
    assert {i["ends"] for i in sweep.items(db, now + 60, cfg) if i["task"]} == {None}
    db.x("DELETE FROM messages WHERE id=?", (mid,))
    assert {i["ends"] for i in sweep.items(db, now + 60, cfg) if i["task"]} == {"user"}
    # So does any change of the pause row (a re-pause, a new reason) ...
    _set_pause_row(db, "board-a", {**row, "reason": "hold for the user: new firmware"})
    assert {i["ends"] for i in sweep.items(db, now + 60, cfg) if i["task"]} == {None}
    _set_pause_row(db, "board-a", row)
    assert {i["ends"] for i in sweep.items(db, now + 60, cfg) if i["task"]} == {"user"}
    # ... and its lift.
    _set_pause_row(db, "board-a", None)
    assert {i["ends"] for i in sweep.items(db, now + 60, cfg) if i["task"]} == {None}
    # A pause the coordinator set is no cover: its outcome keeps no fingerprint.
    coord.pause_resource(p, "board-a", True, reason="flaky", by="coordinator")
    sweep.record(db, {"id": b, "outcome": "human_indispensable", "why": "needs a person"}, None, now + 120)
    assert "pause" not in db.kv(sweep.OUTCOMES_KEY)[f"task:{b}"]
    assert {i["ends"] for i in sweep.items(db, now + 180, cfg) if i["task"]} == {None}


def _covered_by_user_pause(p, now):
    from ttp import sweep
    a, b = _board_work(p, now)
    sweep.record(p.db, {"id": a, "outcome": "human_indispensable", "why": "only the user lifts it"}, None, now + 60)
    assert {i["ends"] for i in sweep.items(p.db, now + 120, p.config()) if i["task"]} == {"user"}
    return a, b


def test_blocker_sweep_a_note_relaying_the_users_verbatim_words_rearms_a_user_pause_cover(env):
    """Another project's note that carries the user's verbatim words (the relay label) ends a user
    pause's cover like a direct user message: the items are judged again. The cover rests on the
    outcome's time, so a later outcome covers them again."""
    from ttp import relay, sweep, upstream
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    _covered_by_user_pause(p, now)
    text = (f"Relaying a user message. {relay.VERBATIM}: \"board-a: lift the pause, the cable is fixed\" "
            f"{relay.CONTEXT}: sent on from the chat")
    assert upstream.send("peer", 3, p.name, text) == "sent"
    assert upstream.ingest(p, cfg, now + 180) == 1
    assert {i["ends"] for i in sweep.items(db, now + 240, cfg) if i["task"]} == {None}
    assert db.kv(sweep.RELAYED_KEY) == now + 180
    sweep.record(db, {"id": _board_ids(db)[0], "outcome": "human_indispensable", "why": "still the user's"},
                 None, now + 300)
    assert {i["ends"] for i in sweep.items(db, now + 360, cfg) if i["task"]} == {"user"}


def _board_ids(db):
    return [t["id"] for t in db.q("SELECT id FROM tasks ORDER BY id")]


def test_blocker_sweep_a_note_with_only_relayer_context_keeps_a_user_pause_cover(env):
    """A note whose user part is empty or missing (the relayer's own context only, or a plain worker
    note), and a note the other project's daemon routed, are no user word: the cover holds."""
    from ttp import relay, sweep, upstream
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    _covered_by_user_pause(p, now)
    notes = [f"{relay.CONTEXT}: the user may lift the board-a pause soon",
             f"{relay.VERBATIM}: {relay.CONTEXT}: the user said to lift board-a",
             "board-a: lift the pause, the cable is fixed"]
    for k, text in enumerate(notes):
        assert upstream.send("peer", k + 1, p.name, text) == "sent"
    assert upstream.send("peer", None, p.name, f"{relay.VERBATIM}: lift board-a", sender="daemon") == "sent"
    assert upstream.ingest(p, cfg, now + 180) == 4
    assert db.kv(sweep.RELAYED_KEY) is None
    assert {i["ends"] for i in sweep.items(db, now + 240, cfg) if i["task"]} == {"user"}
    assert not relay.carries_user_words(f"{relay.VERBATIM}: {relay.MARK} only context")
    assert relay.carries_user_words(f"USER\u2019S WORDS (VERBATIM) \"go ahead\"")


@pytest.mark.parametrize("stored", ["human_indispensable", {"outcome": "human_indispensable", "ts": 0,
                                                            "pause": "board-a", "why": "old format"}])
def test_blocker_sweep_an_old_format_outcome_is_no_cover_and_never_crashes_the_sweep(env, stored):
    """An outcome stored in an older format (a plain string, or a `pause` that is no fingerprint map)
    is no cover: the sweep judges the item again, and every reader of the outcomes skips it."""
    from ttp import coordinator as coord, sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    a, b = _board_work(p, now)
    stored = {**stored, "ts": now} if isinstance(stored, dict) else stored
    db.set_kv(sweep.OUTCOMES_KEY, {f"task:{a}": stored, f"task:{b}": stored})
    assert sweep.pause_covers(db) == {}
    live = sweep.items(db, now + 60, cfg)
    assert {i["ends"] for i in live if i["task"]} == {None}
    assert sweep.due(db, cfg, now + 60)
    eid = sweep.start(db, cfg, "every 6h", now + 60)
    assert f"- #{a} " in coord.digest(p, {}, [eid], [])
    sweep.review_lines(db, now + 7 * 3600, 0.0)
    sweep.flags(db, db.kv(sweep.STATE_KEY), live, now + 120)
    sweep.record(db, {"id": a, "outcome": "human_indispensable", "why": "only the user lifts it"}, None, now + 180)
    outs = db.kv(sweep.OUTCOMES_KEY)
    assert set(outs) == {f"task:{a}"} if isinstance(stored, str) else {f"task:{a}", f"task:{b}"}
    assert {i["ends"] for i in sweep.items(db, now + 240, cfg) if i["task"]} == {"user"}


def test_blocker_sweep_while_every_item_ends_with_the_user_only_a_pause_ending_brings_it_forward(env):
    """While every live item is a hold no turn lifts, unrelated signals (a budget kind change, resolved
    upstream notes) do not bring the sweep forward; a pause ending or a built-in re-arm signal does, and
    with any item a turn could act on, every signal counts again."""
    from ttp import coordinator as coord, sweep
    p = make(env)
    db, cfg, t = p.db, p.config(), time.time()
    a, b = _board_work(p, t)
    now = t + 2 * 3600
    sweep.start(db, cfg, "every 6h", t)
    db.x("UPDATE events SET status='handled'")
    sweep.record(db, {"id": a, "outcome": "human_indispensable", "why": "only the user lifts it"}, None, t + 60)
    assert all(i["ends"] == "user" for i in sweep.items(db, now, cfg))
    sweep.signal(db, "claude budget changed: plan -> api")
    sweep.signal(db, "upstream notes resolved: 0123abcd")
    assert sweep.due(db, cfg, now) is None
    # A built-in re-arm signal still counts: an ask resolved since the last sweep.
    from ttp import unblock
    db.set_kv(unblock.RESOLVED_KEY, {"7": {"ts": now - 60}})
    assert sweep.due(db, cfg, now) == "ask #7 resolved"
    db.set_kv(unblock.RESOLVED_KEY, {})
    # A pause ending (pauseends' signal, or a pause the last sweep saw gone) brings it forward.
    sweep.signal(db, "pause ended: board-b", rearm=True)
    assert sweep.due(db, cfg, now) == "pause ended: board-b"
    db.set_kv(sweep.SIGNAL_KEY, [{"ts": now - 60, "why": "claude budget changed: plan -> api"}])
    coord.pause_resource(p, "board-c", True, reason="hold", by="user")
    state = db.kv(sweep.STATE_KEY)
    db.set_kv(sweep.STATE_KEY, {**state, "paused": [*state["paused"], "board-d"]})
    assert sweep.due(db, cfg, now) == "pause ended: board-d"
    db.set_kv(sweep.STATE_KEY, state)
    assert sweep.due(db, cfg, now) is None
    # An item a turn could act on: the unrelated signal counts again.
    other = db.add_task("needs a key")
    db.update_task(other, status="blocked", blocked_reason="needs the vendor's key")
    assert sweep.due(db, cfg, now) == "claude budget changed: plan -> api"


def test_blocker_sweep_keeps_its_6h_floor_while_every_item_ends_with_the_user(env):
    """Unrelated signals wait for the interval, not forever: past blocker_sweep_h they start the sweep."""
    from ttp import sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    a, _ = _board_work(p, now)
    sweep.start(db, cfg, "every 6h", now)
    db.x("UPDATE events SET status='handled'")
    sweep.record(db, {"id": a, "outcome": "human_indispensable", "why": "only the user lifts it"}, None, now + 60)
    sweep.signal(db, "upstream notes resolved: 0123abcd")
    assert sweep.due(db, cfg, now + 5 * 3600) is None
    assert sweep.due(db, cfg, now + 6 * 3600) == "upstream notes resolved: 0123abcd"


def _ask_held(p, now, ref="blocking:review"):
    """A blocked task whose only lift is an open ask, judged human_indispensable by a sweep at `now`."""
    from ttp import coordinator as coord, sweep
    db, cfg = p.db, p.config()
    aid = db.post("out", "Sign the vendor contract?", kind="ask", ref=ref)
    db.x("UPDATE messages SET ts=? WHERE id=?", (now - 600, aid))
    tid = db.add_task("sign the vendor contract")
    db.update_task(tid, status="blocked", blocked_reason=f"waiting on the answer to ask {aid}")
    assert sweep.due(db, cfg, now) == "every 6h"
    sweep.start(db, cfg, "every 6h", now)
    db.x("UPDATE events SET status='handled'")
    assert coord.apply(p, [{"type": "sweep", "id": tid, "outcome": "human_indispensable",
                            "why": "only the user can sign it"}]) == []
    assert db.kv(sweep.OUTCOMES_KEY)[f"task:{tid}"]["ask"] == aid
    return aid, tid


def _live(db, cfg, key, at):
    from ttp import sweep
    return next(i for i in sweep.items(db, at, cfg) if i["key"] == key)


def test_blocker_sweep_carries_a_hold_only_an_open_ask_can_lift_and_starts_no_sweep(env):
    """A blocked task whose outcome names one open ask as its only lift is carried without a turn: no
    interval sweep, no budget kind change brings one forward, and a sweep lists it HELD BY OPEN ASK."""
    from ttp import coordinator as coord, sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    aid, tid = _ask_held(p, now)
    key = f"task:{tid}"
    i = _live(db, cfg, key, now + 7 * 3600)
    assert i["ask"]["id"] == aid and i["ask"]["held"] and sweep.carried(db.kv(sweep.OUTCOMES_KEY)[key], i, now + 7 * 3600)
    assert sweep.due(db, cfg, now + 7 * 3600) is None, "every item ask-held: no interval sweep"
    sweep.signal(db, "claude budget changed: plan -> api")
    sweep.signal(db, "claude account changed")
    for h in (2, 7, 20):
        assert sweep.due(db, cfg, now + h * 3600) is None, h
    # A sweep that runs anyway (another item) carries it with no action and no flag.
    eid = sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    state = db.kv(sweep.STATE_KEY)
    assert key in state["carried"] and not state["flags"] and not state["loops"]
    line = next(ln for ln in coord.digest(p, {}, [eid], []).splitlines() if ln.startswith(f"- #{tid} "))
    assert f"| HELD BY OPEN ASK {aid} (no action): last re-check" in line, line
    db.x("UPDATE events SET status='handled'")
    assert sweep.due(db, cfg, now + 9 * 3600) is None
    # A coordinator-set resource pause waiting on the same ask is carried the same way, until its row changes.
    coord.pause_resource(p, "board-a", True, reason=f"until ask {aid} is answered", by="coordinator")
    eid = sweep.start(db, cfg, "every 6h", now + 9 * 3600)
    db.x("UPDATE events SET status='handled'")
    assert sweep.record(db, {"resource": "board-a", "outcome": "human_indispensable", "why": "the user decides"},
                        None, now + 9 * 3600 + 60) == "resource:board-a"
    assert sweep.due(db, cfg, now + 16 * 3600) is None
    _set_pause_row(db, "board-a", {**db.paused_resources()["board-a"], "until": now + 30 * 3600})
    assert not _live(db, cfg, "resource:board-a", now + 16 * 3600)["ask"]["held"]
    assert sweep.due(db, cfg, now + 16 * 3600) == "every 6h"


def test_blocker_sweep_mixed_items_with_one_not_carried_still_sweep_on_a_budget_kind_change(env):
    from ttp import sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    _ask_held(p, now)
    other = db.add_task("needs a key")
    db.update_task(other, status="blocked", blocked_reason="needs the vendor's key")
    sweep.signal(db, "claude budget changed: plan -> api")
    assert sweep.due(db, cfg, now + 2 * 3600) == "claude budget changed: plan -> api"
    assert sweep.due(db, cfg, now + 7 * 3600) == "every 6h"


@pytest.mark.parametrize("change", ["answered", "withdrawn", "user message", "relayed words", "reason", "spec",
                                    "second ask"])
def test_blocker_sweep_ask_held_hold_comes_back_once_anything_it_rests_on_changes(env, change):
    from ttp import sweep, unblock
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    aid, tid = _ask_held(p, now)
    key = f"task:{tid}"
    assert sweep.due(db, cfg, now + 7 * 3600) is None
    if change in ("answered", "withdrawn"):
        db.x("UPDATE messages SET handled=1 WHERE id=?", (aid,))
        if change == "answered":
            db.set_kv(unblock.RESOLVED_KEY, {str(aid): {"ts": now + 3600}})
            assert sweep.due(db, cfg, now + 2 * 3600) == f"ask #{aid} resolved"
    elif change == "user message":
        db.post("in", "signed it", chat="c1", kind="user")
    elif change == "relayed words":
        sweep.user_words_relayed(db, time.time() + 1)
    elif change == "reason":
        db.update_task(tid, blocked_reason=f"waiting on the answer to ask {aid}; legal also asked")
    elif change == "spec":
        db.x("UPDATE tasks SET spec=? WHERE id=?", ("sign it in blue ink", tid))
    else:
        other = db.post("out", "Which entity signs?", kind="ask", ref="blocking:review")
        db.update_task(tid, blocked_reason=f"waiting on ask {aid} and ask {other}")
    i = _live(db, cfg, key, now + 7 * 3600)
    assert not (i.get("ask") or {}).get("held")
    assert not sweep.carried(db.kv(sweep.OUTCOMES_KEY)[key], i, now + 7 * 3600)
    assert sweep.due(db, cfg, now + 7 * 3600) == "every 6h"


def test_blocker_sweep_ask_held_hold_comes_back_past_ask_rethink_h_and_at_the_daily_re_check(env):
    from ttp import sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    # An ask askrethink may raise (blocking: human): carried until ask_rethink_h (2h) passes since it opened.
    aid, tid = _ask_held(p, now, ref="blocking:human")
    key = f"task:{tid}"
    assert _live(db, cfg, key, now + 3600)["ask"]["held"]
    assert not _live(db, cfg, key, now + 3 * 3600)["ask"]["held"]
    assert sweep.due(db, cfg, now + 7 * 3600) == "every 6h"
    # The turn that rethinks it records human_indispensable again: carried again.
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    db.x("UPDATE events SET status='handled'")
    sweep.record(db, {"id": tid, "outcome": "human_indispensable", "why": "only the user signs"}, None, now + 7 * 3600 + 60)
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # The daily re-check: a turn judges it again RECHECK_H after the outcome, brought forward by its signal.
    sweep.start(db, cfg, "every 6h", now + 28 * 3600)   # another item's sweep, say
    db.x("UPDATE events SET status='handled'")
    assert key in db.kv(sweep.STATE_KEY)["carried"]
    later = now + 7 * 3600 + 60 + sweep.RECHECK_H * 3600 + 60
    assert not _live(db, cfg, key, later)["ask"]["held"]
    assert sweep.due(db, cfg, later) == f"daily re-check due: {key}"
    assert not sweep.flags(db, db.kv(sweep.STATE_KEY), sweep.items(db, later, cfg), later)
    # A still_blocked naming the ask is carried past its next check the same way.
    sweep.start(db, cfg, "daily", later)
    db.x("UPDATE events SET status='handled'")
    sweep.record(db, {"id": tid, "outcome": "still_blocked", "until": f"ask {aid} is answered"}, later + 3600, later + 60)
    assert db.kv(sweep.OUTCOMES_KEY)[key]["ask"] == aid
    assert sweep.due(db, cfg, later + 3 * 3600) is None
    # ... but not one with a probe: something else may lift it.
    sweep.record(db, {"id": tid, "outcome": "still_blocked", "until_probe": "test -e out/signed"}, later + 3600,
                 later + 120)
    assert "ask" not in db.kv(sweep.OUTCOMES_KEY)[key]
    assert sweep.due(db, cfg, later + 3 * 3600) == f"next check due: {key}"


def test_blocker_sweep_item_newly_covered_by_a_user_pause_ignores_flags_raised_before_it(env):
    """A task flagged at the last sweep (no outcome) that a user pause's human_indispensable then covers
    carries without that old flag, so an interval sweep is skipped while nothing else is stuck."""
    from ttp import coordinator as coord, sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    a, b = _board_work(p, now)
    sweep.start(db, cfg, "every 6h", now)
    db.x("UPDATE events SET status='handled'")
    eid = sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    db.x("UPDATE events SET status='handled'")
    assert set(db.kv(sweep.STATE_KEY)["flags"]) == {f"task:{a}", f"task:{b}"}
    sweep.record(db, {"id": a, "outcome": "human_indispensable", "why": "only the user lifts it"}, None,
                 now + 7 * 3600 + 60)
    state, outs = db.kv(sweep.STATE_KEY), db.kv(sweep.OUTCOMES_KEY)
    live = {i["key"]: i for i in sweep.items(db, now + 8 * 3600, cfg)}
    assert sweep._carries(live[f"task:{b}"], state, outs, now + 8 * 3600)
    assert "HELD BY USER PAUSE (no action)" in next(ln for ln in coord.digest(p, {}, [eid], []).splitlines()
                                                    if ln.startswith(f"- #{b} "))
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # A loop a later sweep raised on a covered item (a model-free hold loop) still counts.
    db.set_kv(sweep.STATE_KEY, {**state, "last": now + 7 * 3600 + 120, "loops": {f"task:{b}": "loop: x"}})
    assert not sweep._carries(live[f"task:{b}"], db.kv(sweep.STATE_KEY), outs, now + 8 * 3600)


def test_blocker_sweep_replay_of_a_day_of_unrelated_signals_over_user_paused_work(env):
    """The upstream note's day: deferred tasks held only by a user-set resource pause, a sweep that
    records human_indispensable for them, then budget kind changes and resolved upstream notes every
    few hours. Before, 7 of those signals each brought a sweep forward that re-judged the same tasks;
    now none does, and only the 6h floor sweeps run, every item carried."""
    from ttp import sweep
    p = make(env)
    db, cfg, t0 = p.db, p.config(), time.time()
    tasks = _board_work(p, t0, n=3)
    eid = sweep.start(db, cfg, sweep.due(db, cfg, t0), t0)
    db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    for t in tasks:
        sweep.record(db, {"id": t, "outcome": "human_indispensable", "why": "only the user lifts the pause"},
                     None, t0 + 60)
    signals = {1.5: "claude budget changed: plan -> api", 3: "upstream notes resolved: 01", 4.5: "upstream notes resolved: 02",
               8: "codex budget changed: api -> plan", 10: "upstream notes resolved: 03", 14: "upstream notes resolved: 04",
               20: "claude budget changed: api -> plan"}
    sweeps = []
    for step in range(1, 24 * 4 + 1):      # the daemon's check every 15 minutes
        h = step / 4
        now = t0 + h * 3600
        if h in signals:
            sweep.signal(db, signals[h])
        why = sweep.due(db, cfg, now)
        if why:
            eid = sweep.start(db, cfg, why, now)
            db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
            state = db.kv(sweep.STATE_KEY)
            sweeps.append((h, not state["flags"] and set(state["carried"]) >= {f"task:{t}" for t in tasks}))
    hours = [h for h, _ in sweeps]
    early = [b for a, b in zip([0.0, *hours], hours) if b - a < 6]
    assert not early, f"sweeps brought forward at {early}h by unrelated signals"
    assert 1 <= len(sweeps) <= 4 and all(carried for _, carried in sweeps), sweeps


def _watched_holds(p, now):
    """A coordinator pause on board-b with an end_when probe and an end ahead, and a task deferred on a
    start_when probe; both probes last said not yet, and a sweep judged both still_blocked with a 2h
    next check."""
    from ttp import sweep, startgate
    db = p.db
    _set_pause_row(db, "board-b", {"by": "coordinator", "reason": "fabric repair", "since": now - 3600,
                                   "until": now + 3 * 86400, "end_when": "test -e out/board-b-ok"})
    tid = db.add_task("bench after the repair", labels=["start_when:test -e out/repaired",
                                                        f"deferred_since:{now - 600}"])
    _probe_says(db, tid, 1, now)
    eid = sweep.start(db, p.config(), "every 6h", now)
    db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
    for a in ({"id": tid}, {"resource": "board-b"}):
        sweep.record(db, {**a, "outcome": "still_blocked", "until": "the repair is done and its probe passes",
                          "until_probe": "test -e out/repaired"}, now + 7200, now + 60)
    assert all(o.get("fp") for o in sweep.outcomes(db).values()), "each outcome keeps the hold's fingerprint"
    assert startgate.KEY in [r["key"] for r in db.q("SELECT key FROM kv")]
    return tid


def _probe_says(db, tid, rc, at):
    from ttp import sweep, startgate
    startgate.record(db, tid, "test -e out/repaired", rc, "not yet", at)
    db.set_kv(sweep.PAUSE_PROBES_KEY, {"board-b": {"probe": "test -e out/board-b-ok", "rc": rc, "at": at}})


def test_blocker_sweep_skips_watched_holds_whose_probe_and_fingerprint_are_unchanged(env):
    """The upstream note's case: holds whose end a model-free probe already watches were re-judged at
    every sweep (each a tricky turn answering still_blocked again). While the probe still says not
    yet and nothing about the hold changed, the outcome carries past its next check and no sweep starts,
    not on the interval and not on an unrelated signal."""
    from ttp import sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    tid = _watched_holds(p, now)
    later = now + 7 * 3600            # past both next checks and the 6h interval
    _probe_says(db, tid, 1, later - 60)
    live = {i["key"]: i for i in sweep.items(db, later, cfg)}
    outs = sweep.outcomes(db)
    assert all(sweep.watched(outs[k], live[k], later) for k in (f"task:{tid}", "resource:board-b"))
    assert sweep.due(db, cfg, later) is None
    sweep.signal(db, "claude budget changed: plan -> api")
    assert sweep.due(db, cfg, later) is None, "an unrelated signal brings no sweep either"
    # A probe that says busy (75) or host unreachable (255) is still not yet.
    _probe_says(db, tid, 75, later)
    assert sweep.due(db, cfg, later) is not None, "a new exit code is a change"
    # When another item does need a sweep, the watched holds are listed CARRIED with no action.
    _probe_says(db, tid, 1, later)
    other = db.add_task("waits on a decision")
    db.update_task(other, status="blocked", blocked_reason="needs a decision")
    assert sweep.due(db, cfg, later) == "every 6h"
    eid = sweep.start(db, cfg, "every 6h", later)
    assert set(db.kv(sweep.STATE_KEY)["carried"]) == {f"task:{tid}", "resource:board-b"}
    assert not db.kv(sweep.STATE_KEY)["flags"]
    text = "\n".join(sweep.digest_lines(db, [eid], later, cfg))
    line = next(ln for ln in text.splitlines() if ln.startswith(f"- #{tid} "))
    assert "CARRIED (no action)" in line and "probe still says not yet" in line
    assert "board-b" in db.paused_resources(), "the sweep lifts nothing"


@pytest.mark.parametrize("change", ["passed", "broken", "stale", "reason", "message", "until", "ledger", "never"])
def test_blocker_sweep_re_judges_a_watched_hold_once_anything_about_it_changes(env, change):
    from ttp import machine_ledger as ml, sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    tid = _watched_holds(p, now)
    later = now + 7 * 3600
    _probe_says(db, tid, 1, later - 60)
    assert sweep.due(db, cfg, later) is None
    row = dict(db.paused_resources()["board-b"])
    if change == "passed":
        _probe_says(db, tid, 0, later - 30)
    elif change == "broken":
        _probe_says(db, tid, 2, later - 30)
    elif change == "stale":
        _probe_says(db, tid, 1, later - sweep.PROBE_FRESH_S - 60)
    elif change == "reason":
        _set_pause_row(db, "board-b", {**row, "reason": "fabric repair; the vendor now says next week"})
    elif change == "message":
        db.x("INSERT INTO messages(ts, direction, chat, kind, text) VALUES(?,?,?,?,?)",
             (later - 600, "in", "c1", "user", "board-b is fixed, try it"))
    elif change == "until":
        _set_pause_row(db, "board-b", {**row, "until": later - 60})
    elif change == "ledger":
        from ttp import machines as mm
        mm.add("board", tags="device")
        ml.add_change("board", "repair firmware flashed", "reflash the old image", "other", expires="6h", now=later - 600)
    else:   # a hold with no probe is swept as before
        _set_pause_row(db, "board-b", {k: v for k, v in row.items() if k != "end_when"})
    live = {i["key"]: i for i in sweep.items(db, later, cfg)}
    outs = sweep.outcomes(db)
    gone = [k for k in ("resource:board-b", f"task:{tid}") if not sweep.watched(outs[k], live[k], later)]
    assert gone == (["resource:board-b", f"task:{tid}"] if change in ("passed", "broken", "stale")
                    else ["resource:board-b"]), gone
    assert sweep.due(db, cfg, later) == "every 6h"
    sweep.start(db, cfg, "every 6h", later)
    assert "resource:board-b" not in db.kv(sweep.STATE_KEY)["carried"]


def test_blocker_sweep_re_judges_an_unchanged_watched_hold_once_a_day(env):
    from ttp import sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    tid = _watched_holds(p, now)
    for h in (7, 13, 19, 23.5):
        _probe_says(db, tid, 1, now + h * 3600 - 60)
        assert sweep.due(db, cfg, now + h * 3600) is None, h
    day = now + 60 + sweep.RECHECK_H * 3600 + 120
    _probe_says(db, tid, 1, day - 60)
    assert sweep.due(db, cfg, day) == "every 6h"
    eid = sweep.start(db, cfg, "every 6h", day)
    state = db.kv(sweep.STATE_KEY)
    assert state["carried"] == [] and state["flags"] == {}, "a due daily re-check is an item, not a FLAG"
    assert "CARRIED" not in "\n".join(sweep.digest_lines(db, [eid], day, cfg)).split("\n", 1)[1]
    # A fresh judgement restarts the window.
    db.x("UPDATE events SET status='handled'")
    sweep.record(db, {"id": tid, "outcome": "still_blocked", "until": "the repair is done and its probe passes",
                      "until_probe": "test -e out/repaired"}, day + 7200, day + 60)
    sweep.record(db, {"resource": "board-b", "outcome": "still_blocked", "until": "the repair is done and its probe passes",
                      "until_probe": "test -e out/board-b-ok"}, day + 7200, day + 60)
    _probe_says(db, tid, 1, day + 7 * 3600)
    assert sweep.due(db, cfg, day + 7 * 3600) is None


def test_blocker_sweep_daily_re_check_signal_and_pause_probe_verdicts_are_kept(env):
    """The daily re-check comes due between interval sweeps as a signal; the daemon keeps each pause
    probe's last verdict for the sweep."""
    from ttp import coordinator as coord, pauseends, sweep
    p = make(env)
    db, cfg, now = p.db, p.config(), time.time()
    tid = _watched_holds(p, now)
    db.set_kv(sweep.STATE_KEY, {**db.kv(sweep.STATE_KEY), "last": now + 22 * 3600})
    other = db.add_task("waits on a decision")
    db.update_task(other, status="blocked", blocked_reason="needs a decision")
    sweep.record(db, {"id": other, "outcome": "still_blocked", "until": "the vendor answers the ticket",
                      "until_probe": "test -e out/answer"}, now + 5 * 86400, now + 60)
    day = now + 60 + sweep.RECHECK_H * 3600 + 120
    _probe_says(db, tid, 1, day - 60)
    assert "daily re-check due: task:" in (sweep.due(db, cfg, day) or "")
    assert coord.apply(p, [{"type": "resource_pause", "resource": "rig", "paused": True,
                            "end_when": "exit 1", "reason": "flaky"}]) == []
    pe = pauseends.PauseEnds(p)
    pe.tick(now)
    for proc, _, _ in list(pe._procs.values()):
        proc.wait(10)
    pe.tick(now + 1)
    assert db.kv(sweep.PAUSE_PROBES_KEY)["rig"] == {"probe": "exit 1", "rc": 1, "at": now + 1}


def test_blocker_sweep_replay_of_a_day_of_signals_over_probe_watched_holds(env):
    """The upstream note's day: holds a probe watches (pauses with end_when, tasks with start_when),
    their next checks every 2h, and budget changes and resolved notes every few hours. Before, each
    next check and signal brought a tricky-turn sweep that answered still_blocked again; now only the
    daily re-check does."""
    from ttp import sweep
    p = make(env)
    db, cfg, t0 = p.db, p.config(), time.time()
    tid = _watched_holds(p, t0)
    signals = {1.5: "claude budget changed: plan -> api", 3: "upstream notes resolved: 01", 4.5: "upstream notes resolved: 02",
               8: "codex budget changed: api -> plan", 10: "upstream notes resolved: 03", 14: "upstream notes resolved: 04",
               20: "claude budget changed: api -> plan"}
    sweeps = []
    for step in range(1, 30 * 4 + 1):      # the daemon's check every 15 minutes, for 30h
        h = step / 4
        now = t0 + h * 3600
        _probe_says(db, tid, 1, now - 60)
        if h in signals:
            sweep.signal(db, signals[h])
        why = sweep.due(db, cfg, now)
        if why:
            eid = sweep.start(db, cfg, why, now)
            db.x("UPDATE events SET status='handled' WHERE id=?", (eid,))
            sweeps.append(h)
            for a in ({"id": tid}, {"resource": "board-b"}):
                sweep.record(db, {**a, "outcome": "still_blocked", "until": "the repair is done and its probe passes",
                                  "until_probe": "test -e out/repaired"}, now + 7200, now + 60)
    assert len(sweeps) == 1 and 24 < sweeps[0] <= 30, sweeps



def _held_sweep(p, monkeypatch, before=None):
    """A daemon whose stuck items each end without a turn: a user-set resource pause, a task blocked until
    a time ahead, a wait on a retry_when probe and a deferral on a start_when probe whose last answers are
    a fresh not yet, and a task blocked on an open ask. The first sweep at T0 runs the model, after
    `before(db, t0, ids)` adds to them."""
    from ttp import anchors, coordinator as coord, daemon as dm, startgate, sweep, sweepskip
    db, t0 = p.db, time.time()
    clock = [t0]
    monkeypatch.setattr(time, "time", lambda: clock[0])
    coord.pause_resource(p, "board-u", True, reason="hold for the user", by="user")
    dep = db.add_task("the fixture it builds on")
    db.update_task(dep, status="running")
    until = db.add_task("blocked until the window", depends_on=[dep])
    db.update_task(until, status="blocked", blocked_reason="the lab window opens later",
                   labels=[anchors.label("until", str(t0 + 3 * 86400))])
    waiting = db.add_task("waits on a build")
    db.update_task(waiting, status="waiting", result=json.dumps(
        {"status": "waiting", "summary": "build", "retry_when": "test -e out/w", "waiting_since": t0}))
    aid = db.post("out", "Which vendor key?", kind="ask", ref="blocking:review")
    asked = db.add_task("needs the vendor key")
    db.update_task(asked, status="blocked", blocked_reason=f"waiting on the answer to ask {aid}",
                   labels=[anchors.label("ask", str(aid))])
    deferred = db.add_task("bench after the repair", labels=["start_when:test -e out/d", f"deferred_since:{t0 - 600}"])
    db.x("UPDATE messages SET handled=1 WHERE direction='in'")   # the coordinator read its inbox
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    d.cfg.setdefault("waiting", {})["max_hold_s"] = 2 * 86400

    def at(ts):
        """Move to `ts`; both probes answered not yet a minute ago."""
        clock[0] = ts
        d._probe_rc[waiting] = (1, ts - 60, "test -e out/w")
        startgate.record(db, deferred, "test -e out/d", 1, "not yet", ts - 60)

    def run(ts=None):
        """One blocker_sweep check at `ts`: the queued sweep event's id (None if none), the receipts."""
        if ts is not None:
            at(ts)
        d._sweep_checked = 0.0
        d.blocker_sweep()
        ev = db.one("SELECT id FROM events WHERE kind=? AND status='queued'", (sweep.SWEEP_KIND,))
        if ev:
            db.x("UPDATE events SET status='handled' WHERE id=?", (ev["id"],))
        return (ev or {}).get("id"), db.kv(sweepskip.RECEIPTS_KEY) or []

    ids = {"until": until, "waiting": waiting, "asked": asked, "deferred": deferred, "dep": dep, "aid": aid}
    if before:
        before(db, t0, ids)
    eid, recs = run(t0)
    assert eid and not recs, "no model sweep on record: the first one runs the model"
    return d, db, t0, at, run, ids


def test_blocker_sweep_skips_model_free_when_every_item_is_held_and_unchanged(env, monkeypatch):
    """An unchanged sweep whose every item ends without a turn is skipped: a receipt lists each item and
    its end, resets the 6-h clock, shows as one low status line and feed row, and the daily review counts
    it; past 24 h a model sweep runs again."""
    from ttp import audit, cli, sweep, sweepskip, web
    p = make(env)
    d, db, t0, at, run, ids = _held_sweep(p, monkeypatch)
    db.x("INSERT INTO runs(role, status, cost_usd) VALUES('coordinator','done',0.5)")
    model = db.kv(sweepskip.MODEL_KEY)
    assert model["ts"] == t0 and len(model["fps"]) == 5
    t1 = t0 + 6 * 3600 + 60
    eid, recs = run(t1)
    assert eid is None, "every item held and unchanged: no sweep turn"
    [rec] = recs
    assert rec["ts"] == t1 and rec["model"] == t0 and rec["usd"] == 0.5
    ends = dict(rec["items"])
    assert ends.pop("resource:board-u") == "user pause"
    assert ends.pop(f"task:{ids['until']}").startswith("until ")
    assert ends.pop(f"task:{ids['waiting']}") == "retry_when `test -e out/w`"
    assert ends.pop(f"task:{ids['asked']}") == f"open ask #{ids['aid']}"
    assert ends.pop(f"task:{ids['deferred']}") == "start_when test -e out/d"
    assert not ends
    # The receipt resets the 6-h clock.
    assert sweep.due(db, d.cfg, t1) is None and sweep.due(db, d.cfg, t1 + 5 * 3600) is None
    assert sweep.due(db, d.cfg, t1 + 6 * 3600) == "every 6h"
    # One low status line and feed row, never an alert.
    line = "blocker sweep skipped model-free"
    assert line in cli.status_text(p) and "5 item(s) unchanged" in sweepskip.status_lines(db, t1, p)[0]
    rows = [m for m in web.state_payload(p, db)["feed"] if line in (m.get("text") or "")]
    assert [(m["severity"], m["state"]) for m in rows] == [("low", "status")]
    assert not db.one("SELECT id FROM events WHERE severity IN ('high','critical')")
    # The daily review counts model and skipped sweeps and the saving.
    assert sweepskip.counts(db, t0 - 60, t1 + 60) == {"model": 1, "skipped": 1, "usd": 0.5}
    assert any("blocker sweeps: 1 by the model, 1 skipped model-free" in ln and "~$0.50 saved" in ln
               for ln in audit.lines(db, t1 + 60)), audit.lines(db, t1 + 60)
    # A second interval skips again; once the model sweep is 24 h old, the model runs.
    assert run(t1 + 6 * 3600 + 60)[0] is None and len(db.kv(sweepskip.RECEIPTS_KEY)) == 2
    eid, recs = run(t0 + 24 * 3600 + 60)
    assert eid and len(recs) == 2 and db.kv(sweepskip.MODEL_KEY)["ts"] == t0 + 24 * 3600 + 60
    assert sweepskip.latest(db) is None and sweepskip.status_lines(db, t0 + 24 * 3600 + 60, p) == []


def _never_skip(case, p, d, db, t1, ids):
    from ttp import anchors, coordinator as coord, sweep
    if case == "new item":
        n = db.add_task("another window")
        db.update_task(n, status="blocked", blocked_reason="later", labels=[anchors.label("until", str(t1 + 86400))])
    elif case == "changed item":
        db.update_task(ids["until"], blocked_reason="the lab window moved")
    elif case == "broken probe":
        d._probe_rc[ids["waiting"]] = (2, t1 - 60, "test -e out/w")
    elif case == "stale probe":
        d._probe_rc[ids["waiting"]] = (1, t1 - 2 * 3600, "test -e out/w")
    elif case == "overdue wait":
        d.cfg["waiting"]["max_hold_s"] = 3600
    elif case == "deferral past defer_max_days":
        d.cfg.setdefault("coordinator", {})["defer_max_days"] = 0.001
    elif case == "coordinator pause":
        coord.pause_resource(p, "board-c", True, reason="fabric repair", by="coordinator")
    elif case in ("failed", "cancelled"):
        db.update_task(ids["dep"], status=case)
    elif case == "missing dependency":
        db.update_task(ids["until"], depends_on=[ids["dep"] + 1000])
    elif case == "review past backlog":
        r = db.add_task("a change to review")
        db.update_task(r, status="review")
        db.add_task("review it", kind="review", depends_on=[r])
        db.x("UPDATE tasks SET updated=? WHERE id=?", (t1 - 7 * 3600, r))
    elif case == "pushing past backlog":
        r = db.add_task("a change being pushed")
        db.x("UPDATE tasks SET status='pushing', updated=? WHERE id=?", (t1 - 7 * 3600, r))
    elif case == "no model-free end":
        n = db.add_task("needs a decision")
        db.update_task(n, status="blocked", blocked_reason="needs a decision")
    elif case == "pending signal":
        sweep.signal(db, "provider pause over: codex")
    elif case == "unhandled message":
        db.post("in", "any news?")
    elif case == "queued event":
        db.x("INSERT INTO events(ts,source,kind,severity,text,status) VALUES(?,?,?,?,?,?)",
             (t1 - 60, "daemon", "task_failed", "normal", "#9 failed", "queued"))
    elif case == "next check due":
        # A turn judged the until-blocked task still blocked and asked for a re-check before now.
        sweep.record(db, {"id": ids["until"], "outcome": "still_blocked", "until": "the window opens",
                          "until_probe": "test -e out/window"}, t1 - 60, t1 - 6 * 3600)
    elif case == "daily re-check due":
        # A turn judged the ask-held task a day ago, after the user last spoke: its daily re-check came due.
        db.x("UPDATE messages SET ts=? WHERE direction='in'", (t1 - 2 * 86400,))
        sweep.record(db, {"id": ids["asked"], "outcome": "human_indispensable", "why": "only the user answers"},
                     None, t1 - 24 * 3600 - 60)


@pytest.mark.parametrize("case, why", [
    ("new item", "items changed"), ("changed item", "items changed"),
    ("broken probe", "no model-free end"), ("stale probe", "no model-free end"),
    ("overdue wait", "no model-free end"), ("deferral past defer_max_days", "no model-free end"),
    ("coordinator pause", "no model-free end: resource:board-c"),
    ("failed", "no model-free end"), ("cancelled", "no model-free end"), ("missing dependency", "no model-free end"),
    ("review past backlog", "no model-free end"), ("pushing past backlog", "a task is pushing past"),
    ("no model-free end", "no model-free end"), ("pending signal", "a signal is pending"),
    ("unhandled message", "a message waits"), ("queued event", "another event needs a turn"),
    ("next check due", "next check due: task:"), ("daily re-check due", "daily re-check due: task:"),
])
def test_blocker_sweep_never_skips_what_a_turn_must_judge(env, monkeypatch, case, why):
    """Each case that needs a turn queues the model sweep instead of a receipt, from a state that skips."""
    from ttp import sweep, sweepskip
    p = make(env)
    d, db, t0, at, run, ids = _held_sweep(p, monkeypatch)
    t1 = t0 + 6 * 3600 + 60
    at(t1)
    assert sweepskip.check(db, d.cfg, sweep.items(db, t1, d.cfg), t1, d._probe_rc.get)["skip"], "the control skips"
    _never_skip(case, p, d, db, t1, ids)
    got = sweepskip.check(db, d.cfg, sweep.items(db, t1, d.cfg), t1, d._probe_rc.get)
    assert not got["skip"] and why in got["why"], got["why"]
    eid, recs = run()
    assert eid and recs == [], f"{case}: a model sweep, no receipt"


def _coordinator_pause_sweep(p, monkeypatch, end, by="coordinator"):
    """_held_sweep plus a pause of board-c `by` with `end`, judged by a model sweep a minute after T0.
    Returns the check at the next interval (T0 + 6 h + 2 min) through `again`, after `change` if given."""
    from ttp import coordinator as coord, sweep, sweepskip
    d, db, t0, at, run, ids = _held_sweep(p, monkeypatch)
    end = end(t0) if callable(end) else end
    coord.pause_resource(p, "board-c", True, reason="fabric repair", by=by, end=end)
    t1, t2 = t0 + 60, t0 + 6 * 3600 + 120

    def again(change=None, ts=t2):
        at(ts)
        db.set_kv(sweep.PAUSE_PROBES_KEY, {"board-c": {"probe": "test -e out/c", "rc": 1, "at": ts - 60}})
        if change:
            change(d, db, ts)
        return sweepskip.check(db, d.cfg, sweep.items(db, ts, d.cfg), ts, d._probe_rc.get, p.name)
    sweepskip.swept(db, again(ts=t1), t1)
    return d, db, t0, again


@pytest.mark.parametrize("end, rule", [
    ({"end_when": "test -e out/c"}, "probe: end_when `test -e out/c`"),
    ({"end_when": {"heal": "board-c-up", "healthy_n": 3, "clean_s": 1800}}, "heal: heal check `board-c-up` lifts it"),
    (lambda t0: {"until": t0 + 8 * 3600}, "end before the next sweep: until"),
])
def test_blocker_sweep_skip_counts_a_coordinator_pause_that_ends_model_free(env, monkeypatch, end, rule):
    """A pause the coordinator set, unchanged since the model sweep, skips the sweep when something
    model-free re-evaluates or ends it first: a working end_when probe, an enabled heal check's health
    end, or (with neither) an `until` before the next interval sweep. The receipt names its rule."""
    from ttp import schedule as sched, sweepskip
    p = make(env)
    sched.upsert(p.db, "board-c-up", "command", "5m", payload={"heal": {"check": "true", "resource": "board-c"}})
    d, db, t0, again = _coordinator_pause_sweep(p, monkeypatch, end)
    got = again()
    assert got["skip"], got["why"]
    assert got["ends"]["resource:board-c"].startswith(rule)
    rec = sweepskip.skip(db, got, "every 6h", time.time())
    assert ["resource:board-c", got["ends"]["resource:board-c"]] in rec["items"]


