def test_blocker_sweep_skip_keeps_an_unchanged_user_pause_beside_a_coordinator_pause(env, monkeypatch):
    """A user pause is lifted on their word only: unchanged, it still skips whatever its end, beside a
    coordinator pause its probe ends; the receipt names each with its rule."""
    from ttp import coordinator as coord, sweepskip
    p = make(env)
    d, db, t0, again = _coordinator_pause_sweep(p, monkeypatch, {"end_when": "test -e out/c"})
    coord.pause_resource(p, "board-v", True, reason="vendor visit", by="user", end={"until": t0 + 5 * 86400})
    sweepskip.swept(db, again(ts=t0 + 120), t0 + 120)
    got = again()
    assert got["skip"], got["why"]
    assert got["ends"]["resource:board-v"] == "user pause"
    assert got["ends"]["resource:board-c"] == "probe: end_when `test -e out/c`"


def _resleep_sweep(p, monkeypatch):
    """_held_sweep plus what the daemon re-writes between sweeps while nothing changes: a time-deferred task
    (its start_after long past, kept asleep by a retry_when that still says not yet) whose not_before moves
    on each hourly probe, and "; next try <time>" in its and the waiting task's reasons. `resleep(ts)` is one
    such probe at `ts`."""
    from ttp import timefmt

    def resleep(db, ts, ids):
        nb = ts + 3600
        for k in ("timed", "waiting"):
            db.update_task(ids[k], blocked_reason=f"waiting for the user's sign-in; its probe says not yet; next "
                                                  f"try {timefmt.short(nb, None)}")
        db.update_task(ids["timed"], not_before=nb)

    def before(db, t0, ids):
        ids["timed"] = db.add_task("verify the tool once the user signs in",
                                   labels=[f"start_after:{t0 - 3 * 86400}", f"deferred_since:{t0 - 3 * 86400 - 3600}"])
        resleep(db, t0, ids)
    d, db, t0, at, run, ids = _held_sweep(p, monkeypatch, before)
    return d, db, t0, at, run, ids, lambda ts: resleep(db, ts, ids)


def test_blocker_sweep_skip_ignores_the_times_the_daemon_rewrites_between_sweeps(env, monkeypatch):
    """Two sweeps over an unchanged stuck set skip the second: a time-deferred task's not_before, which the
    daemon pushes on at each still-failing hourly probe (its "starts after" reason and end with it), a
    reason's "; next try" time, and a review that came and went between the sweeps change nothing a turn
    judges."""
    from ttp import sweep, sweepskip
    p = make(env)
    d, db, t0, at, run, ids, resleep = _resleep_sweep(p, monkeypatch)
    timed = f"task:{ids['timed']}"
    first = sweep.items(db, t0, d.cfg)
    assert {i["key"]: i["ends"] for i in first}[timed] == "time"
    r = db.add_task("a change to review")   # a short-lived review item between the sweeps
    db.update_task(r, status="review")
    db.update_task(r, status="done")
    for h in range(1, 7):
        resleep(t0 + h * 3600)
    t1 = t0 + 6 * 3600 + 60
    at(t1)
    live = sweep.items(db, t1, d.cfg)
    was = {i["key"]: i["reason"] for i in first}
    assert {i["key"]: i["reason"] for i in live}[timed] != was[timed], "the not_before moved"
    got = sweepskip.check(db, d.cfg, live, t1, d._probe_rc.get)
    assert got["skip"], got["why"]
    eid, recs = run(t1)
    assert eid is None and len(recs) == 1
    assert dict(recs[0]["items"])[timed].startswith("starts after ")


def test_blocker_sweep_fingerprint_drops_only_the_times_the_daemon_writes(env):
    """The fingerprint ignores a time-only deferral's not_before (its "starts after <time>" reason and end) and
    a reason's "; next try <time>" tail, in the daemon's own formats only: a reason or end a turn wrote that
    reads alike still counts."""
    from ttp import sweepskip
    p = make(env)
    db, now = p.db, time.time()
    t = p.db.add_task("verify once the user signs in", labels=[f"start_after:{int(now) - 86400}"])
    db.update_task(t, not_before=now + 3600)

    def fp(reason, e="", ends="time"):
        i = {"key": f"task:{t}", "kind": "deferred", "task": t, "status": "queued", "spec_sha": "s",
             "reason": reason, "ends": ends}
        return sweepskip._fp(db, i, e)
    assert fp("starts after 2026-10-24 20:52 UTC", "starts after 2026-10-24 20:52 UTC") == \
        fp("starts after 2026-10-25 01:52 PDT", "starts after 2026-10-25 01:52 PDT")
    assert fp("waiting for sign-in; its probe says not yet; next try 16:52 PDT") == \
        fp("waiting for sign-in; its probe says not yet; next try Sat 09:10 PDT")
    assert fp("starts after the lab opens") != fp("starts after the vendor ships")
    assert fp("held; next try after the vendor replies") != fp("held; next try after the lab opens")
    assert fp("waiting; its probe says not yet; next try 16:52 PDT") != \
        fp("waiting; its probe says host unreachable; next try 16:52 PDT")
    assert fp("r", "until 2026-10-24 20:52 UTC", ends=None) != fp("r", "until 2026-10-25 20:52 UTC", ends=None)
    was = fp("r")
    db.update_task(t, labels=[f"start_after:{int(now) - 3600}"])   # a deliberate re-deferral counts
    assert fp("r") != was


def _real_change(case, p, d, db, ts, ids):
    from ttp import anchors
    if case == "status":
        db.update_task(ids["deferred"], status="waiting", labels=[], result=json.dumps(
            {"status": "waiting", "summary": "bench", "retry_when": "test -e out/d", "waiting_since": ts - 60}))
        d._probe_rc[ids["deferred"]] = (1, ts - 60, "test -e out/d")
        return f"task:{ids['deferred']} kind/status/"
    if case == "spec":
        db.update_task(ids["until"], spec="blocked until the window, on the second bench")
        return f"task:{ids['until']} spec"
    if case == "dependency state":
        db.update_task(ids["dep"], status="queued")
        return f"task:{ids['until']} deps"
    if case == "new item":
        n = db.add_task("another window")
        db.update_task(n, status="blocked", blocked_reason="later", labels=[anchors.label("until", str(ts + 86400))])
        return f"+task:{n}"
    if case == "removed item":
        db.update_task(ids["asked"], status="cancelled")
        return f"-task:{ids['asked']}"
    if case == "re-deferred":   # a deliberate start_after again ahead: a planned deferral, no longer stuck
        db.update_task(ids["timed"], labels=[f"start_after:{ts + 86400}"], not_before=ts + 86400)
        return f"-task:{ids['timed']}"
    raise AssertionError(case)


@pytest.mark.parametrize("case", ["status", "spec", "dependency state", "new item", "removed item", "re-deferred"])
def test_blocker_sweep_skip_still_turns_on_a_real_change_and_names_it(env, monkeypatch, case):
    """With the daemon's re-written times ignored, a real change since the model sweep still starts a turn,
    and its reason names the item and what changed ("task:12 spec", "+task:13", "-task:9")."""
    from ttp import sweep, sweepskip
    p = make(env)
    d, db, t0, at, run, ids, resleep = _resleep_sweep(p, monkeypatch)
    t1 = t0 + 6 * 3600 + 60
    at(t1)
    resleep(t1)
    assert sweepskip.check(db, d.cfg, sweep.items(db, t1, d.cfg), t1, d._probe_rc.get)["skip"], "the control skips"
    want = _real_change(case, p, d, db, t1, ids)
    got = sweepskip.check(db, d.cfg, sweep.items(db, t1, d.cfg), t1, d._probe_rc.get)
    assert not got["skip"] and got["why"].startswith("items changed: ") and want in got["why"], got["why"]
    eid, recs = run()
    assert eid and recs == [], f"{case}: a model sweep, no receipt"


def test_task_add_of_a_review_of_an_accepted_head_is_refused_unless_forced_with_a_reason(env, monkeypatch):
    from ttp import coordinator as coord, reviewreuse
    p = make(env)
    tid, path, branch = _code_task(p, "make it")
    _commit_file(path, "a")
    d, started = _reuse_daemon(p, monkeypatch)
    first = _reuse_review(p, tid)
    d.dispatch()
    p.db.update_task(first, status="done", result=json.dumps({"status": "done", "summary": "ok"}))
    add = {"type": "task_add", "title": f"Review #{tid} again", "kind": "review", "spec": "check it",
           "depends_on": [tid]}
    problems = coord.apply(p, [add])
    assert len(problems) == 1 and f"review #{first}" in problems[0] and "force" in problems[0]
    assert len(coord.apply(p, [dict(add, force=True)])) == 1, "force needs a reason"
    assert coord.apply(p, [dict(add, force=True, reason="the first review skipped the docs")]) == []
    forced = p.db.one("SELECT * FROM tasks WHERE title=?", (add["title"],))
    assert reviewreuse.FORCED_LABEL in json.loads(forced["labels"])
    p.db.update_task(forced["id"], provider="claude")
    d.dispatch()
    assert started == [first, forced["id"]], "a forced review runs"



def test_a_refused_resend_carries_the_whole_approved_charter_text_to_the_next_turn(env):
    p = make(env)
    from ttp import coordinator as coord
    db = p.db
    p.charter_path.write_text(RESTR_CHARTER)
    said = db.post("in", "goals: as below", chat=None, channel="web", kind="user", provenance="web-session")
    approved = " ".join(f"Keep docs page {i} generic, with no setup details." for i in range(45))
    assert len(approved) > 2000
    act = {"type": "charter_update", "section": "Restrictions", "replaces": "Restrictions (added", "text": approved}
    assert "matches 2" in coord.apply(p, [act], turn=1, user_turn=True, messages=[said])[0]
    # A later turn rewords it: refused, with the approved text whole and the file that holds it.
    err = coord.apply(p, [{**act, "replaces": "Restrictions (added 2026-10-01, turn 3.0)", "text": approved[:-1] + "!"}], turn=2)
    assert len(err) == 1 and "was for other text" in err[0] and repr(approved) in err[0], err
    [rec] = db.kv(coord.CHARTER_APPROVALS_KEY)
    path = f"tt-project/state/charter-approved/{rec['id']}.txt"
    assert path in err[0] and (p.root / path).read_text() == approved
    # Both ways it reaches the next turn keep it whole: the rejected line and the immediate retry.
    db.set_kv(coord.REJECTED_KEY, err)
    ids = [r["id"] for r in db.q("SELECT id FROM events WHERE kind='charter_retry' AND status='queued'")]
    assert len(ids) == 1
    d = coord.digest(p, {}, ids, [])
    assert d.count(repr(approved)) == 2 and "[cut]" not in d, d
    # The same text resent: applied.
    assert coord.apply(p, [{**act, "replaces": "Restrictions (added 2026-10-01, turn 3.0)"}], turn=13) == []
    assert approved in p.charter_path.read_text()



def test_empty_cache_ttl_is_auto_flagged_by_doctor_and_set_to_auto_by_upgrade(env):
    from ttp import cli, coordinator
    from ttp.project import config_problems
    p = make(env)
    assert coordinator.cache_ttl_s({"cache_ttl": ""}) == coordinator.cache_ttl_s({}) == 3600.0
    assert coordinator.cache_ttl_s({"cache_ttl": "5m"}) == 300.0
    assert not any("cache_ttl" in line for line in config_problems(p.raw_config()))
    assert cli._auto_cache_ttl(p) == ""                  # unset: nothing to change
    p.set_config("coordinator.cache_ttl", "")
    assert any('cache_ttl: ""' in line for line in config_problems(p.raw_config()))
    assert "upgrade note" in cli._auto_cache_ttl(p)
    assert p.raw_config()["coordinator"]["cache_ttl"] == "auto"
    assert not any("cache_ttl" in line for line in config_problems(p.raw_config()))
    p.set_config("coordinator.cache_ttl", "5m")         # the project's own choice stays
    assert cli._auto_cache_ttl(p) == ""
    assert p.raw_config()["coordinator"]["cache_ttl"] == "5m"



def test_promise_due_reads_only_real_month_names_and_bounds_dates():
    """Words that start like a month ('decision 2', 'marker 3', 'JUnit 5') are not dates; a real date
    within PROMISE_DATE_MAX_D days is kept and one further out keeps only its clock time."""
    from datetime import datetime
    from zoneinfo import ZoneInfo
    from ttp import obligations as ob
    tz = ZoneInfo("America/Los_Angeles")
    now = datetime(2026, 10, 15, 10, 0, tzinfo=tz).timestamp()
    at_15 = datetime(2026, 10, 15, 15, 0, tzinfo=tz).timestamp()
    for text in ("I will report the decision 2 results by 15:00", "I'll post the marker 3 numbers by 15:00",
                 "I'll share the JUnit 5 results by 15:00"):
        assert ob.promise_due(text, now, tz) == at_15, text
    assert ob.promise_due("I'll deliver it Oct 15 at 15:00", now, tz) == at_15
    assert ob.promise_due("I'll deliver it October 17 at 3pm", now, tz) == \
        datetime(2026, 10, 17, 15, 0, tzinfo=tz).timestamp()
    assert ob.promise_due("I'll deliver it Dec 2 at 15:00", now, tz) == at_15, "a date weeks out is a misread"
    for offer in ("Shall I report it by 15:00?", "Want me to share the sha by 15:00", "Should I deliver it by 3pm?"):
        assert ob.commitments(offer) == [], offer



def test_promise_is_recorded_beside_an_unrelated_obligation_and_linked_to_its_own(env, monkeypatch):
    """An obligation in the same batch never suppresses a chat promise. It is linked only when one of
    its owners is a batch task replying to the promise's chat, and the promise closes with it."""
    from ttp import coordinator as coord
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    other = p.db.add_task("unrelated", "s", kind="work", tier="light", origin="coordinator")
    assert coord.apply(p, [{"type": "obligation", "text": "unrelated report", "owners": [other]},
                           {"type": "reply", "chat": "c1", "text": "I'll report the sha by 15:00."}]) == []
    promise = next(o for o in ob.items(p.db) if o.get("promise"))
    assert promise["promise"]["chat"] == "c1" and promise["promise"]["obligations"] == []
    p.db.update_task(tid, reply_chat="c2")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "priority": 2},
                           {"type": "obligation", "text": "the bench numbers", "owners": [tid]},
                           {"type": "obligation", "key": "o1", "owners": [other]},
                           {"type": "reply", "chat": "c2", "text": "I'll deliver the bench numbers by 16:00."}]) == []
    linked = next(o for o in ob.items(p.db) if o.get("promise") and o["promise"]["chat"] == "c2")
    own = next(o["id"] for o in ob.items(p.db) if o["text"] == "the bench numbers")
    assert linked["promise"]["obligations"] == [own] and linked["promise"]["tasks"] == [tid]
    ob.record(p, own, "receipt", "bench numbers posted", None)
    check(now + 60)
    assert ob.get(p.db, linked["id"])["receipt"], "the promise closes with its linked obligation"
    assert not ob.get(p.db, promise["id"])["receipt"], "the unlinked promise stays open"



def _pdt(h, m=0, day=15):
    from datetime import datetime
    from zoneinfo import ZoneInfo
    return datetime(2026, 10, day, h, m, tzinfo=ZoneInfo("America/Los_Angeles")).timestamp()


def _promise_events(p):
    return p.db.q("SELECT * FROM events WHERE kind='promise_overdue' ORDER BY id")


def _next_message_id(p, n):
    """The next message posted gets id `n` (a replay of real message numbers)."""
    mid = p.db.post("in", "filler", chat="c0", handled=True)
    p.db.x("UPDATE messages SET id=? WHERE id=?", (n - 1, mid))


I_WILL_DELIVER = "I'll deliver a dogfood-2 candidate sha with checks by around 15:00 PDT on Oct 15."


def test_promise_replay_671_recorded_listed_overdue_and_raised_once(env, monkeypatch):
    """Reply #671 at 11:00 PDT promises a candidate by 15:00 PDT with no task behind it: one promise
    record due 15:00 PDT, shown OVERDUE at 17:20 in the digest section and the blocker sweep, and exactly
    one high promise_overdue event across repeated checks, which is a tricky-turn trigger."""
    from ttp import coordinator as coord
    from ttp import obligations as ob
    from ttp import sweep
    p, d, _, _, check = _ob_setup(env, monkeypatch)
    p.set_config("home_timezone", "America/Los_Angeles")
    _next_message_id(p, 671)
    monkeypatch.setattr(time, "time", lambda: _pdt(11))
    assert coord.apply(p, [{"type": "reply", "chat": "c1", "text": "Checks are running. " + I_WILL_DELIVER}]) == []
    [o] = ob.open_promises(p.db)
    pr = o["promise"]
    assert (pr["chat"], pr["message"], pr["due"], pr["timed"], pr["tasks"]) == ("c1", 671, _pdt(15), True, [])
    assert "dogfood-2 candidate" in o["text"] and "Checks are running" not in o["text"]
    check(_pdt(14, 59))
    assert _promise_events(p) == [] and ob.promise_lines(p.db, _pdt(14, 59), p)[0].endswith(
        "(send each deliverable or an honest update in its chat; close with `obligation` key + evidence)")
    head, line = ob.promise_lines(p.db, _pdt(17, 20), p)
    assert "1 open, 1 OVERDUE" in head
    assert "chat c1, message #671" in line and "15:00 PDT" in line and "OVERDUE 2.3 h" in line
    for at in (_pdt(17, 20), _pdt(17, 50), _pdt(19), _pdt(23)):
        check(at)
    [ev] = _promise_events(p)
    assert ev["fingerprint"] == f"obligation:{o['id']}:promise:{int(_pdt(15))}" and ev["severity"] == "high"
    assert "promise_overdue" in coord.effort_triggers(p.db, p.config(), [ev["id"]], None, now=_pdt(17, 20))[0]
    [item] = [i for i in sweep.items(p.db, _pdt(17, 20), p) if i["kind"] == "promise"]
    assert (item["key"], item["status"], item["ends"]) == (f"promise:{o['id']}", "overdue", None)
    assert [i["status"] for i in sweep.items(p.db, _pdt(12), p) if i["kind"] == "promise"] == ["promised"]


def test_promise_owner_task_links_resend_merges_and_done_plus_reply_closes(env, monkeypatch):
    """A batch task replying to the promise's chat owns it; the same promise sent again merges its tasks
    and obligations into the one record; once every owner is done, a later reply to that chat closes it
    (a reply to another chat does not)."""
    from ttp import coordinator as coord
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    monkeypatch.setattr(time, "time", lambda: now)
    said = "I'll report the candidate sha by 15:00."
    assert coord.apply(p, [{"type": "task_add", "title": "cut candidate", "spec": "s", "reply_chat": "c1"},
                           {"type": "reply", "chat": "c1", "text": said}]) == []
    new = p.db.one("SELECT id FROM tasks WHERE title='cut candidate'")["id"]
    [o] = ob.open_promises(p.db)
    assert o["promise"]["tasks"] == [new] and o["promise"]["obligations"] == []
    p.db.update_task(tid, reply_chat="c1")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "priority": 2},
                           {"type": "obligation", "text": "the candidate sha", "owners": [tid]},
                           {"type": "reply", "chat": "c1", "text": said}]) == []
    own = next(x["id"] for x in ob.items(p.db) if x["text"] == "the candidate sha")
    [o] = ob.open_promises(p.db)
    assert o["promise"]["tasks"] == sorted([new, tid]) and o["promise"]["obligations"] == [own]
    assert any(f"promise {o['id']} in chat c1 updated" in n for n in p.db.kv(coord.NOTES_KEY))
    for t in (new, tid):
        p.db.update_task(t, status="done")
    monkeypatch.setattr(time, "time", lambda: now + 60)
    check(now + 60)
    assert ob.get(p.db, o["id"])["receipt"] is None, "owners done, but nothing reached the chat yet"
    assert coord.apply(p, [{"type": "reply", "chat": "c2", "text": "Other news."}]) == []
    check(now + 120)
    assert ob.get(p.db, o["id"])["receipt"] is None, "a reply to another chat keeps nothing"
    assert coord.apply(p, [{"type": "reply", "chat": "c1", "text": "Candidate sha is abc123."}]) == []
    check(now + 180)
    assert "finished; reply #" in ob.get(p.db, o["id"])["receipt"]["evidence"]


def test_promise_not_recorded_for_non_commitments_questions_or_offers(env, monkeypatch):
    from ttp import coordinator as coord
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    texts = ("The build passed at 15:00.", "I reported the sha at 15:00.", "I will not deliver it by 15:00.",
             "We'll never report back.", "Will you send the sha by 15:00?", "I'll report back by 15:00?",
             "If you want, I'll report the sha by 15:00.", "Should I share the numbers by 3pm",
             "Would you like me to post the results by 15:00", "Want me to deliver it in 2 hours.",
             "Checks take about 90 min.")
    for text in texts:
        assert ob.commitments(text) == [], text
    assert coord.apply(p, [{"type": "reply", "chat": "c1", "text": t} for t in texts]) == []
    assert ob.items(p.db) == []


PROMISE_CORPUS_POS = (
    "I'll post each result here as it comes in.",
    "I'll post the per-tray count here.",
    "When the task hands off, I'll post the root cause and the PR link here.",
    "Once the run ends I'll post the numbers.",
    "I'll send the comparison table once both runs finish.",
    "We'll open a PR with the fix after the checks pass.",
    "I'll open the pull request when the review is clean.",
    "I'll share the log link when it is uploaded.",
    "We will post the final table here tomorrow.",
    "I'm going to post the bisect result here.",
    "The checks are green, and it goes up as the draft PR for you to merge.",
    "The fix goes up as a draft PR after the review.",
    "Once reviewed, the change goes up as the PR.",
    "I'll report back when the sweep finishes.",
    "I'll let you know once the board is free.",
    "I'll post the results.",
    "We'll send you the trace link here.",
    "I'll post a short summary of each failure here.",
    "I will send the per-chip numbers after the rerun.",
    "I'll post the perf numbers for both configs here.",
)
PROMISE_CORPUS_NEG = (
    "I posted the results here an hour ago.",
    "Should I post the numbers here?",
    "If you want, I'll post the table here.",
    "I'll post it if asked?",
    "We will not post the table here.",
    "The CI bot will post the results here.",
    "I won't open a PR for this one.",
    "It went up as the draft PR yesterday.",
    "If it goes up as a draft PR, CI runs on it.",
    "I would post the numbers here, but the run failed.",
)


def test_promise_shapes_post_object_here_and_goes_up_as_the_pr():
    """'I'll post <up to a few words> here|result|table|PR|numbers|link' and '<it|the fix|the change> goes
    up as (a|the) (draft) PR' are commitments; the common false shapes (another actor, a won't, a past
    'went up', a conditional 'if|when|whether it goes up', a 'would') are not."""
    from ttp import obligations as ob
    for text in ("I'll post each result here as it comes in.", "I'll post the per-tray count here.",
                 "When the task hands off, I'll post the root cause and the PR link here.",
                 "Tests pass, and it goes up as the draft PR for you to merge.",
                 "The fix goes up as a PR once reviewed.", "The change goes up as the draft PR tonight."):
        assert ob.commitments(text) == [text], text
    for text in ("Will you post the numbers here?", "If you want, I'll post the table here.", "I'll post it if asked?",
                 "we will not post the numbers here", "The CI bot will post the results here.",
                 "I won't open a PR for this one.", "It went up as the draft PR yesterday.",
                 "If it goes up as a draft PR, CI runs on it.", "When it goes up as the draft PR, CI runs.",
                 "Whether the fix goes up as a PR is your call.", "I would post the numbers here, but the run failed."):
        assert ob.commitments(text) == [], text


def test_promise_corpus_replay_recall_and_no_false_positives():
    """A fixed generic corpus of 30 chat sentences: at least 90% of the 20 promises are found and none
    of the 10 non-promises."""
    from ttp import obligations as ob
    assert len(PROMISE_CORPUS_POS) + len(PROMISE_CORPUS_NEG) == 30
    found = [s for s in PROMISE_CORPUS_POS if ob.commitments(s) == [s]]
    missed = sorted(set(PROMISE_CORPUS_POS) - set(found))
    assert len(found) / len(PROMISE_CORPUS_POS) >= 0.9, missed
    assert [s for s in PROMISE_CORPUS_NEG if ob.commitments(s)] == []


def _promise_item(oid: str, due: float, closed: float | None = None, dropped: float | None = None) -> dict:
    return {"id": oid, "text": f"promise {oid}", "by": "coordinator", "created": due - 3600, "owners": {},
            "receipt": {"at": closed, "task": None, "evidence": "sent"} if closed is not None else None,
            "dropped": {"at": dropped, "by": "user", "why": "not owed"} if dropped is not None else None,
            "episode": 0, "raised": None, "covered": [],
            "promise": {"chat": "c1", "message": 1, "due": due, "timed": True, "tasks": [], "obligations": [],
                        "raised": None}}


def test_promise_audit_line_counts_kept_on_time_late_and_overdue_open(env):
    """Three promises due in the last 24 h: one closed before its due time, one 5 h after it, one still
    open: 2 kept (1 late, max 5.0 h) and 1 overdue and open. Promises due outside the window, not yet
    due, or plain obligations do not count; the audit's lines and `ttp audit --json` carry it."""
    from ttp import audit
    from ttp import obligations as ob
    p = make(env)
    now = time.time()
    st = ob._load(p.db)
    st["items"] = {o["id"]: o for o in (
        _promise_item("o1", now - 10 * 3600, closed=now - 11 * 3600),
        _promise_item("o2", now - 8 * 3600, closed=now - 3 * 3600),
        _promise_item("o3", now - 2 * 3600),
        _promise_item("o4", now - 30 * 3600, closed=now - 2 * 3600),
        _promise_item("o5", now + 3600))}
    st["items"]["o6"] = {**_promise_item("o6", now - 3600), "promise": None}
    p.db.set_kv(ob.KV, st)
    line = ob.audit_line(p.db, now - 86400, now)
    assert line == "promises, 24 h: 3 due, 1 kept on time, 1 kept late (max 5.0 h), 1 overdue and open (o3)", line
    assert line in audit.lines(p.db, now)
    row = audit.report(p.db, now)["promises"]
    assert (row["due"], row["on_time"], row["late"], row["max_late_h"], row["open"]) == (3, 1, 1, 5.0, ["o3"])
    st["items"]["o3"]["dropped"] = {"at": now - 3600, "by": "user", "why": "not owed"}
    p.db.set_kv(ob.KV, st)
    assert ob.audit_line(p.db, now - 86400, now) == \
        "promises, 24 h: 3 due, 1 kept on time, 1 kept late (max 5.0 h), 0 overdue and open, 1 dropped"


def test_promise_audit_line_is_empty_with_nothing_due_in_the_window(env):
    from ttp import audit
    from ttp import obligations as ob
    p = make(env)
    now = time.time()
    assert ob.audit_line(p.db, now - 86400, now) == ""
    st = ob._load(p.db)
    st["items"] = {o["id"]: o for o in (_promise_item("o1", now + 3600), _promise_item("o2", now - 30 * 3600))}
    p.db.set_kv(ob.KV, st)
    assert ob.audit_line(p.db, now - 86400, now) == ""
    assert not [x for x in audit.lines(p.db, now) if x.startswith("promises,")]
    assert audit.report(p.db, now)["promises"]["due"] == 0


def test_promise_closes_by_obligation_key_and_by_sweep_outcome(env, monkeypatch):
    """`obligation` with the promise's key and evidence closes it and retires its queued overdue event;
    a blocker sweep `closed` outcome closes another, which then leaves the sweep."""
    from ttp import coordinator as coord
    from ttp import obligations as ob
    from ttp import sweep
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    monkeypatch.setattr(time, "time", lambda: now)
    assert coord.apply(p, [{"type": "reply", "chat": "c1", "text": "I'll share the numbers in 30 min."},
                           {"type": "reply", "chat": "c2", "text": "I'll post the results in 30 min."}]) == []
    a, b = (o["id"] for o in ob.open_promises(p.db))
    check(now + 3600)
    assert [e["status"] for e in _promise_events(p)] == ["queued", "queued"]
    monkeypatch.setattr(time, "time", lambda: now + 3700)
    assert coord.apply(p, [{"type": "obligation", "key": a, "evidence": "numbers posted in c1"}]) == []
    assert ob.get(p.db, a)["receipt"]["evidence"] == "numbers posted in c1"
    assert {e["fingerprint"].split(":")[1]: e["status"] for e in _promise_events(p)} == {a: "handled", b: "queued"}
    assert coord.apply(p, [{"type": "sweep", "promise": b, "outcome": "closed", "why": "results posted"}]) == []
    assert "results posted" in ob.get(p.db, b)["receipt"]["evidence"]
    assert [e["status"] for e in _promise_events(p)] == ["handled", "handled"]
    assert ob.open_promises(p.db) == [] and ob.promise_lines(p.db, now + 3700) == []
    assert not [i for i in sweep.items(p.db, now + 3700) if i["kind"] == "promise"]
    check(now + 7200)
    assert len(_promise_events(p)) == 2, "a closed promise never raises again"


def test_promise_due_units_past_dates_and_far_dates_keep_the_clock_time():
    """'in 90 min', '3pm', '15:00 UTC', 'tomorrow 09:30'; a date already past falls through to the next
    occurrence of its clock time, and so does a date too far ahead to be meant (the time is what was
    promised); no time at all is None (the default applies)."""
    from datetime import datetime, timezone
    from zoneinfo import ZoneInfo
    from ttp import obligations as ob
    tz = ZoneInfo("America/Los_Angeles")
    now = _pdt(10)
    cases = {"I'll report back in 90 min.": now + 5400, "We'll have it ready in 2 hours.": now + 7200,
             "I'll share it by 3pm.": _pdt(15), "I'll share it by 9am.": _pdt(9, day=16),
             "ETA 15:00 UTC.": datetime(2026, 10, 16, 15, 0, tzinfo=timezone.utc).timestamp(),
             "ETA 18:00 UTC.": datetime(2026, 10, 15, 18, 0, tzinfo=timezone.utc).timestamp(),
             "I'll post the results tomorrow 09:30.": _pdt(9, 30, day=16),
             "I'll send Oct 14 results by 15:00.": _pdt(15),
             "I'll deliver it by 3pm on Jan 2.": _pdt(15),
             "I'll deliver it on Oct 20 at 08:00.": _pdt(8, day=20)}
    for text, due in cases.items():
        assert ob.promise_due(text, now, tz) == due, text
    assert ob.promise_due("I'll report back soon.", now, tz) is None


def test_promise_closes_with_its_linked_obligation_receipt_or_drop_without_a_reply(env, monkeypatch):
    from ttp import coordinator as coord
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    monkeypatch.setattr(time, "time", lambda: now)
    other = p.db.add_task("second deliverable", "s", kind="work", tier="light", origin="coordinator")
    p.db.update_task(tid, reply_chat="c1")
    p.db.update_task(other, reply_chat="c2")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "priority": 2},
                           {"type": "task_update", "id": other, "priority": 2},
                           {"type": "obligation", "text": "first report", "owners": [tid]},
                           {"type": "obligation", "text": "second report", "owners": [other]},
                           {"type": "reply", "chat": "c1", "text": "I'll deliver the first report by 15:00."},
                           {"type": "reply", "chat": "c2", "text": "I'll deliver the second report by 16:00."}]) == []
    by_chat = {o["promise"]["chat"]: o for o in ob.open_promises(p.db)}
    first, second = (next(o["id"] for o in ob.items(p.db) if o["text"] == t) for t in ("first report", "second report"))
    assert by_chat["c1"]["promise"]["obligations"] == [first] and by_chat["c2"]["promise"]["obligations"] == [second]
    ob.record(p, first, "receipt", "report at reports/first.md", None, now=now + 60)
    ob.drop(p, second, "the user withdrew it", now=now + 60)
    check(now + 120)
    assert "linked " + first + " closed" in ob.get(p.db, by_chat["c1"]["id"])["receipt"]["evidence"]
    assert "linked " + second + " closed" in ob.get(p.db, by_chat["c2"]["id"])["receipt"]["evidence"]
    assert not p.db.q("SELECT id FROM messages WHERE direction='out' AND kind='reply' AND ts>?", (now + 1,))


