def _standing_memory_project(env):
    """A project with 14 memory entries: standing preferences (for workers, unaddressed, one that
    speaks of workers, and two for the coordinator), large pinned restrictions, resources and entries
    for workers that overflow the workers' pinned room, and ordinary decisions and facts."""
    p = make(env)
    items = [("STANDING-PLAIN-1: reply in plain words.", None),
             ("STANDING-PLAIN-2: name each run's spend in its hand-off.", None),
             ("STANDING-WORKERS-3: workers report each allocation they hold.", None),
             ("STANDING-TAGGED-4: keep each change on its own branch.", "workers"),
             ("STANDING-COORD-5: answer the user within a day.", "coordinator"),
             ("STANDING-COORD-6: plan the week on Mondays.", "coordinator")]
    paths = {}
    for i, (text, aud) in enumerate(items):
        paths[text.split(":")[0]] = p.add_memory(text, kind="preference", title=f"standing {i}", standing=True,
                                                 audience=aud)
    p.add_memory("RULE-BIG never reboot a box mid-job. " + "r" * 2500, kind="restriction", title="rule big")
    p.add_memory("BOX-BIG box A keeps its data on the scratch disk. " + "b" * 2500, kind="resource", title="box big")
    p.add_memory("TAGGED-BIG benchmarks run warm. " + "t" * 2500, kind="decision", title="tagged big",
                 audience="workers")
    p.add_memory("DECISION-1 the cache stays on.", kind="decision", title="decision 1")
    p.add_memory("DECISION-2 builds use the release profile.", kind="decision", title="decision 2")
    for i in range(3):
        p.add_memory(f"FACT-{i} the nightly run took {i + 1} h.", kind="fact", title=f"fact {i}")
    assert len(p._memory_entries()) == 14
    return p, paths


@pytest.mark.parametrize("tier", ["light", "standard", "deep"])
@pytest.mark.parametrize("kind", ["code", "work", "question", "review", "plan", "harness"])
def test_every_worker_prompt_carries_every_standing_entry_for_workers(env, kind, tier):
    """Every worker run's memory block carries each standing entry meant for workers (no audience, or
    `workers`), whatever the kind, tier or memory budget; only entries that are not standing are
    trimmed, and standing entries for the coordinator stay out."""
    p, _ = _standing_memory_project(env)
    from ttp.prompts import worker_context, worker_system
    task = {"id": 1, "kind": kind, "tier": tier, "title": f"{kind}: tidy the nightly report",
            "spec": "Edit notes/report.md only."}
    system = worker_system(p, task)
    block = system[system.index("# PROJECT MEMORY"):]
    for want in ("STANDING-PLAIN-1", "STANDING-PLAIN-2", "STANDING-WORKERS-3", "STANDING-TAGGED-4"):
        assert want in block, (want, block[:2000])
    for gone in ("STANDING-COORD-5", "STANDING-COORD-6"):
        assert gone not in system, gone
    use = worker_context(p, task)[2]
    assert use["pinned_dropped"] > 0, "the fixture must overflow the workers' pinned room"
    assert "STANDING-" not in "".join(x for x in block.splitlines() if x.startswith("(")), "a pointer stands in"


def test_standing_worker_memory_past_its_room_is_kept_whole_and_alerts_once(env):
    """Standing entries for workers that alone outgrow the workers' pinned room are all kept, whole,
    ahead of every other entry, and the coordinator is told once."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp.prompts import worker_context, worker_system
    duties = [p.add_memory(f"DUTY-{i:02} report it each time. " + "s" * 900, kind="preference", title=f"duty {i}",
                           standing=True) for i in range(8)]
    p.add_memory("FACT-1 the nightly run took 2 h.", title="fact 1")
    text, mem, use = worker_context(p)
    assert use["kept_chars"] > use["memory_limit"] and use["pinned_dropped"] == 0, use
    shown = {e["name"] for e in mem}
    assert {d.stem for d in duties} <= shown and use["kept_over"]
    system = worker_system(p)
    for i in range(8):
        assert f"DUTY-{i:02} report it each time. " + "s" * 900 in system, i
    alerts = lambda: p.db.q("SELECT text FROM events WHERE kind='memory_over_budget'")
    coord.memory_budget_check(p)
    coord.memory_budget_check(p)
    assert len(alerts()) == 1, alerts()
    assert "8 restriction, resource and standing entries for workers" in alerts()[0]["text"], alerts()
    for d in duties[1:]:   # fits again: re-armed, silent
        p.forget_memory(d.stem, why="test")
    coord.memory_budget_check(p)
    assert len(alerts()) == 1 and not p.db.kv(coord.MEMORY_ALERT_KEY)


ALWAYS_0 = ["test -e /tmp/fixed || true", "check-board; exit 0", "test -e x || :"]
REAL_ENDS = ["test -e /tmp/fixed || exit 1", "test -e /tmp/fixed", "ttp lock --probe board | grep -q free"]


def test_an_end_probe_that_always_exits_0_is_refused_and_a_real_test_is_kept(env, capsys):
    """A memory or charter until_probe, a pause's or a mute's end_when, and a task's start_when or
    retry_when that tests something and then always exits 0 would end (or start) what waits on it at
    once: each is refused on one line pointing to `|| exit 1`, and nothing is written. A real test is kept,
    and so are `landed:#<id>` and a bare `true` as a task's deliberate "now"."""
    p = make(env)
    p.set_config("delivery.landed_probe", "test -e landed/{id}")   # no push branch: how landed:#<id> is checked
    from ttp import cli, coordinator as coord
    from ttp import screen as scr
    for bad in ALWAYS_0:
        problems = coord.apply(p, [
            {"type": "resource_pause", "resource": "board", "paused": True, "end_when": bad},
            {"type": "memory_add", "text": "Stay off box A for now.", "until_probe": bad},
            {"type": "charter_update", "section": "Restrictions", "text": "Leave the queue alone.", "until_probe": bad},
            {"type": "task_add", "spec": "s", "title": "later", "start_when": bad},
            {"type": "observation_mute", "source": "watcher:hw", "match": "dropped", "end_when": bad}])
        assert len(problems) == 5 and all("always exits 0" in x and "|| exit 1" in x and "\n" not in x
                                          for x in problems), problems
    assert p.db.paused_resources() == {} and scr.mutes(p.db) == []
    assert not p.db.one("SELECT id FROM tasks WHERE title='later'")
    assert [e for e in p._memory_entries() if e.get("end")] == []
    assert "Leave the queue alone." not in p.charter_path.read_text()
    with pytest.raises(SystemExit):
        cli.main(["pause", "demo", "--resource", "board", "--end-when", ALWAYS_0[0]])
    assert "always exits 0" in capsys.readouterr().err
    tid = _due_waiting_task(p, "exit 1")
    with pytest.raises(SystemExit):
        cli.main(["task", "demo", "set-when", str(tid), ALWAYS_0[1]])
    assert "retry_when always exits 0" in capsys.readouterr().err
    assert json.loads(p.db.task(tid)["result"])["retry_when"] == "exit 1"
    deferred = p.db.add_task("deferred", "s", kind="work", tier="light", origin="user")
    assert coord.apply(p, [{"type": "task_update", "id": deferred, "start_when": "test -e x"}]) == []
    problems = coord.apply(p, [{"type": "task_update", "id": deferred, "start_when": ALWAYS_0[0]}])
    assert problems and "start_when always exits 0" in problems[0], problems
    for i, good in enumerate(REAL_ENDS):
        assert coord.apply(p, [
            {"type": "resource_pause", "resource": f"board{i}", "paused": True, "end_when": good},
            {"type": "memory_add", "text": f"Stay off box {i} for now.", "until_probe": good},
            {"type": "task_add", "spec": "s", "title": f"later {i}", "start_when": good},
            {"type": "observation_mute", "source": "watcher:hw", "match": f"dropped {i}", "end_when": good}]) == []
        cli.main(["task", "demo", "set-when", str(tid), good])
        assert json.loads(p.db.task(tid)["result"])["retry_when"] == good
    assert coord.apply(p, [{"type": "task_add", "spec": "s", "title": "after", "start_when": f"landed:#{deferred}"},
                           {"type": "task_add", "spec": "s", "title": "now", "start_when": "true"}]) == []
    # An on_pass_cmd is a command, not a probe: its `|| true` is fine.
    coord.check_probe("cleanup || true", "on_pass_cmd")


def _store_trivial(path, good, bad):
    path.write_text(path.read_text().replace(good, bad))


def test_a_stored_always_0_until_probe_never_retires_its_entry_and_is_reported_once(env):
    """A memory entry or charter section stored with such a probe (before it was refused) is never retired
    by it: the probe never runs and is listed broken (ends.BROKEN_KEY) for the digest. Its expires still
    ends it."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp import ends
    good, bad = "test -e /tmp/fixed || exit 1", "test -e /tmp/fixed || true"
    assert coord.apply(p, [{"type": "memory_add", "text": "Stay off box A for now.", "until_probe": good,
                            "expires": "2d"},
                           {"type": "charter_update", "section": "Restrictions", "text": "Leave the queue alone.",
                            "until_probe": good}], turn=5) == []
    for f in p.memory_dir.glob("*.md"):
        _store_trivial(f, good, bad)
    _store_trivial(p.charter_path, good, bad)
    assert sorted(i["end"]["probe"] for i in ends.temporaries(p)) == [bad, bad]
    e, now = ends.Ends(p), time.time()
    for i in range(3):
        assert e.tick(now + i * (ends.PROBE_EVERY_S + ends.CHECK_EVERY_S)) == []
        assert not e._procs, "never run"
    broken = p.db.kv(ends.BROKEN_KEY)
    assert len(broken) == 2 and all("always exits 0" in v for v in broken.values()), broken
    assert "Leave the queue alone." in p.charter_path.read_text() and len(list(p.memory_dir.glob("*.md"))) == 1
    assert ends.digest_lines(p, now, now) == []   # first seen: listed for the coordinator a day later
    lines = ends.digest_lines(p, now, now + ends.RECHECK_S + 1)
    assert sum("until_probe is broken" in x and "always exits 0" in x for x in lines) == 2, lines
    assert not ends.digest_lines(p, now, now + ends.RECHECK_S + 2), "once a day"
    retired = e.tick(now + 3 * 86400)
    assert len(retired) == 1 and "expired" in retired[0], "its expires still ends the memory entry"
    assert "Leave the queue alone." in p.charter_path.read_text()
    e.stop()


def test_a_stored_always_0_end_when_never_lifts_a_pause_or_ends_a_mute(env):
    """A pause or a mute stored with such an end_when: the probe never runs, it is reported once as a
    broken probe, and the pause keeps its `until` (whose passing is still reported) and the mute its time."""
    p = make(env)
    from ttp import coordinator as coord, pauseends
    from ttp import screen as scr
    good, bad = "test -e /tmp/fixed || exit 1", "test -e /tmp/fixed || true"
    assert coord.apply(p, [{"type": "resource_pause", "resource": "board", "paused": True, "end_when": good,
                            "until": "1d", "reason": "flaky"},
                           {"type": "observation_mute", "source": "watcher:hw", "match": "dropped",
                            "end_when": good, "hours": 6}]) == []
    with p.db.tx():
        paused = p.db.paused_resources()
        p.db.set_kv("paused_resources", {**paused, "board": {**paused["board"], "end_when": bad}})
        mutes = p.db.kv(scr.MUTES_KEY)
        mutes[0]["end_when"] = bad
        p.db.set_kv(scr.MUTES_KEY, mutes)
    assert p.db.paused_resources()["board"]["end_when"] == bad
    until = p.db.paused_resources()["board"]["until"]
    pe, me, now = pauseends.PauseEnds(p), pauseends.MuteEnds(p), time.time()
    for i in range(3):
        at = now + i * (pauseends.PROBE_EVERY_S + pauseends.CHECK_EVERY_S)
        assert pe.tick(at) == (["board"] if i == 0 else []) and me.tick(at) == []
        assert not pe._procs and not me._procs, "never run"
    [due] = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='pause_end_due'")]
    assert "broken" in due and "always exits 0" in due and "passed" not in due, due
    assert p.db.paused_resources()["board"]["until"] == until
    [m] = scr.mutes(p.db)
    assert m["probe_broken"] and "always exits 0" in m["probe_broken"] and m["until"] > now + 5 * 3600
    broken = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='observation'") if "broken" in e["text"]]
    assert len(broken) == 1, broken
    assert pe.tick(until + 1) == ["board"], "its until passing is still reported"
    assert "end time" in p.db.q("SELECT text FROM events WHERE kind='pause_end_due'")[-1]["text"]
    assert pe.tick(until + 1000) == []
    pe.stop()
    me.stop()


def test_a_stored_always_0_task_probe_never_starts_or_wakes_its_task(env, monkeypatch):
    """A start_when or retry_when stored with such a probe is never run: a deferred task stays deferred with one
    deferral_probe_broken event, and a waiting task is not woken by it (only at its timer, as broken)."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    bad = "test -e /tmp/fixed || true"
    coord.apply(p, [{"type": "task_add", "title": "deferred", "spec": "s", "start_when": "test -e /tmp/fixed"}])
    tid = _added(p, "deferred")
    labels = [l.replace("test -e /tmp/fixed", bad) for l in json.loads(p.db.task(tid)["labels"])]
    p.db.update_task(tid, labels=labels)
    waiting = _due_waiting_task(p, bad)
    p.db.update_task(waiting, not_before=time.time() + 3600)
    d = dmod.Daemon(p.base)
    for _ in range(2):
        d.probe_waiting()
        assert tid not in d._probes and waiting not in d._probes, "never run"
    assert not _ready(p, tid) and p.db.task(waiting)["not_before"] > time.time() + 3000
    [ev] = p.db.q("SELECT text FROM events WHERE kind='deferral_probe_broken'")
    assert "always exits 0" in ev["text"], ev["text"]
    # At its timer the waiting task wakes as broken, never as a passed probe.
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 60)
    p.db.update_task(waiting, not_before=time.time() - 1)
    d.probe_waiting()
    d.probe_waiting()
    woke = json.loads(p.db.task(waiting)["result"])["woke"]
    assert _ready(p, waiting) and woke.startswith("probe broken") and "always exits 0" in woke, woke


# Real tests that end in `; exit 0`: an earlier list exits non-zero (or errexit stops at a failing step).
EARLY_EXIT_ENDS = ["test -e /tmp/fixed || exit 1; exit 0", "test -e /tmp/fixed || { echo no; exit 1; }; echo ok; exit 0",
                   'for i in 1 2; do ttp landed "#$i" >/dev/null || exit 1; done; exit 0',
                   "set -e; test -e /tmp/fixed; exit 0"]


def test_a_probe_that_exits_non_zero_before_its_final_exit_0_is_a_real_test(env, monkeypatch):
    """A probe whose earlier list can `exit` non-zero (also inside a loop or { } group), or that turns on
    errexit, is a real test even though it ends in `exit 0`: every wait accepts it and the daemon runs a
    stored one. `|| true`, `; exit 0` and `|| :` endings without such a step stay refused."""
    p = make(env)
    from ttp import coordinator as coord, ends, pauseends
    from ttp import daemon as dmod
    from ttp import screen as scr
    for good in EARLY_EXIT_ENDS + ["test -e x || exit $rc; exit 0", "set -o errexit; test -e x; true",
                                   "if test -e x; then :; else exit 1; fi; exit 0", "test -e x || exit 2 || true"]:
        assert not ends.always_succeeds(good) and not ends.hides_test(good), good
        coord.check_probe(good, "start_when")
        coord.check_probe(good, "retry_when")
        assert ends.from_action({"until_probe": good})["probe"] == good
        assert pauseends.from_action({"end_when": good})["end_when"] == good
    for i, good in enumerate(EARLY_EXIT_ENDS):
        scr.mute(p.db, "watcher:hw", f"dropped {i}", None, end_when=good)
    assert len(scr.mutes(p.db)) == len(EARLY_EXIT_ENDS)
    for bad in ALWAYS_0 + ["test -e x; exit 0", "set +e; test -e x || true", "echo 'exit 1'; exit 0"]:
        assert ends.hides_test(bad), bad
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    tid = _due_waiting_task(p, EARLY_EXIT_ENDS[0])
    d = dmod.Daemon(p.base)
    d._start_probe(tid, EARLY_EXIT_ENDS[0], time.time())
    assert tid in d._probes and d._probes[tid][2] == EARLY_EXIT_ENDS[0], "a stored one starts a real probe"
    d._probes[tid][0].wait(_load_scaled(60))


def _pinned_kinds_project(env):
    """The reported case, with made-up entries: 14 memory entries and a charter whose Goals leave the
    workers only their pinned floor. The standing ones alone outgrow it; a resource and a restriction
    that are not standing, an entry tagged for workers, and ordinary decisions and facts come after."""
    p = make(env)
    p.charter_path.write_text(_LONG_GOALS_CHARTER)
    pins = {}
    pins["RULE-STANDING"] = p.add_memory("RULE-STANDING never patch the device service. " + "r" * 850,
                                         kind="restriction", title="rule standing", standing=True,
                                         audience="workers")
    pins["DUTY-1"] = p.add_memory("DUTY-1 recover a stuck job yourself. " + "s" * 2600, kind="preference",
                                  title="duty 1", standing=True)
    pins["DUTY-2"] = p.add_memory("DUTY-2 make your own operational calls. " + "s" * 1500, kind="preference",
                                  title="duty 2", standing=True)
    pins["HOST-RESOURCE"] = p.add_memory("HOST-RESOURCE box A (alias box-a) is the project's host; the data "
                                         "folder is read-only. " + "h" * 850, kind="resource", title="host")
    pins["RULE-PLAIN"] = p.add_memory("RULE-PLAIN never reboot box A mid-job. " + "q" * 600, kind="restriction",
                                      title="rule plain")
    tagged = p.add_memory("TAGGED-DECISION releases go out on the release branch. " + "t" * 250,
                          kind="decision", title="tagged", audience="workers")
    for i in range(4):
        p.add_memory(f"DECISION-{i} the cache stays on. " + "d" * 500, kind="decision", title=f"decision {i}")
    p.add_memory("COORD-DECISION plan the week on Mondays.", kind="decision", title="coord", audience="coordinator")
    p.add_memory("FACT-1 the nightly run took 2 h.", kind="fact", title="fact 1")
    p.add_memory("FACT-2 the nightly run took 3 h.", kind="fact", title="fact 2", audience="coordinator")
    p.add_memory("FACT-3 workers keep build logs for a week.", kind="fact", title="fact 3")
    assert len(p._memory_entries()) == 14
    return p, pins, tagged


def _memory_block(system):
    return system[system.index("# PROJECT MEMORY"):]


@pytest.mark.parametrize("kind,tier", [("harness", "light"), ("code", "standard"), ("review", "standard"),
                                       ("question", "light"), ("plan", "deep"), ("work", "standard")])
def test_every_worker_prompt_carries_a_resource_entry_that_is_not_standing(env, kind, tier):
    """A resource entry (and a restriction) that is not tagged standing is in every worker run's memory
    block, whatever the kind or tier, even when the standing entries alone fill the workers' room."""
    p, pins, _ = _pinned_kinds_project(env)
    from ttp.prompts import worker_context, worker_system
    task = {"id": 1, "kind": kind, "tier": tier, "title": f"{kind}: tidy the nightly report",
            "spec": "Edit notes/report.md only."}
    use = worker_context(p, task)[2]
    standing = sum(len(e["line"]) + 1 for e in p._memory_entries() if e["standing"])
    assert standing > use["memory_limit"], "the fixture must make the standing entries alone outgrow the workers' room"
    block = _memory_block(worker_system(p, task))
    for want in ("HOST-RESOURCE box A (alias box-a) is the project's host", "RULE-PLAIN never reboot box A"):
        assert want in block, (want, block[:1500])


def test_the_reported_light_harness_run_carries_every_restriction_resource_and_standing_entry(env):
    """The reported case: 14 entries, a light-tier harness run. Every restriction, resource and standing
    entry is there, whole; the entry tagged for workers that no longer fits is pointed to, never dropped
    silently, and the coordinator and `ttp doctor` are told the kept ones outgrow the room."""
    p, pins, tagged = _pinned_kinds_project(env)
    from ttp import coordinator as coord
    from ttp.prompts import worker_context, worker_system
    task = {"id": 1, "kind": "harness", "tier": "light", "title": "harness: tidy the watcher's log",
            "spec": "Shorten the watcher's log lines."}
    text, mem, use = worker_context(p, task)
    shown = {e["name"] for e in mem}
    assert {f.stem for f in pins.values()} <= shown, shown
    block = _memory_block(worker_system(p, task))
    for f in pins.values():
        line = next(e["line"] for e in p._memory_entries() if e["name"] == f.stem)
        assert line in block, f.stem
    assert "COORD-DECISION" not in block and "FACT-2" not in block
    assert tagged.stem not in shown and use["pinned_dropped"] == 1
    assert f"(1 more entries for workers are in {p.memory_dir}/" in block
    line = coord.worker_pinned_line(p)
    assert line.startswith("pinned worker memory over budget: ") and "1 of 6 pinned entries" in line, line
    coord.memory_budget_check(p)
    alerts = p.db.q("SELECT text FROM events WHERE kind='memory_over_budget'")
    assert len(alerts) == 1 and "so 1 of them reach workers only as a pointer" in alerts[0]["text"], alerts


def test_pinned_worker_memory_is_the_same_in_light_standard_and_deep_runs(env):
    """With the same memory, the light, standard and deep tiers carry the same restriction, resource and
    standing entries: none is lost between tiers."""
    p, pins, _ = _pinned_kinds_project(env)
    from ttp.prompts import worker_system
    blocks = {}
    for tier in ("light", "standard", "deep"):
        task = {"id": 1, "kind": "code", "tier": tier, "title": "code: fix the report script",
                "spec": "Change scripts/report.py."}
        block = _memory_block(worker_system(p, task))
        blocks[tier] = {n for n, f in pins.items() if n + " " in block}
    assert blocks["light"] == blocks["standard"] == blocks["deep"] == set(pins), blocks


def test_task_add_chains_a_continuation_after_an_open_task_on_the_same_branch(env):
    # Another continuation of a failed task (or a task carrying its branch) is open: the new one waits
    # until it ends (its label), and dispatch holds it meanwhile. A task on another branch and one sharing
    # files only are not chained this way.
    p = make(env)
    from ttp import coordinator as coord, worktree
    from ttp.daemon import Daemon
    old = p.db.add_task("failed work", "s", kind="code", tier="light", origin="user")
    p.db.update_task(old, status="failed", branch=f"ttp/t{old}-failed-work")
    first = p.db.add_task("redo it", "s", kind="code", tier="light", origin="user", labels=[f"continues:{old}"])
    assert coord.apply(p, [{"type": "task_add", "kind": "code", "title": "redo it again", "spec": "s",
                            "continues": old}]) == []
    new = p.db.one("SELECT * FROM tasks WHERE title='redo it again'")
    assert worktree.lineage_hold(new) == first, new["labels"]
    d = Daemon(p.base)
    assert d._branch_clash(new, {}) == (first, f"branch ttp/t{old}-failed-work")
    p.db.update_task(first, status="failed")
    assert d._branch_clash(p.db.task(new["id"]), {}) is None, "the hold outlived the task it waits for"
    # pr_branch: the same branch chains; another branch does not.
    p.db.update_task(first, status="queued", labels=json.dumps(["pr_branch:feat/x"]))
    assert coord.apply(p, [{"type": "task_add", "kind": "code", "title": "on x", "spec": "s\npr_branch: feat/x"},
                           {"type": "task_add", "kind": "code", "title": "on y", "spec": "s\npr_branch: feat/y"}]) == []
    assert worktree.lineage_hold(p.db.one("SELECT * FROM tasks WHERE title='on x'")) == first
    assert worktree.lineage_hold(p.db.one("SELECT * FROM tasks WHERE title='on y'")) is None


def test_a_landed_start_when_becomes_depends_on_where_no_landing_can_be_checked(env, capsys):
    """With neither delivery.push_branch nor delivery.landed_probe, `start_when landed:#<id>` would
    only ever exit 2. task_add and task_update turn each landing wait of the probe (`landed:#<id>`, or
    a `ttp landed --task <id>` / `#<id>` term of an `&&` chain) into depends_on <id>, keep the other
    terms as the start_when and say so in their note; a probe with `||` is left as written.
    `ttp task add --start-when` and `ttp task set-when` still refuse it, naming depends_on. Either
    key keeps the landed wait as written."""
    from ttp import cli
    from ttp import coordinator as coord
    from ttp.db import deferral, dependency_ids
    p = make(env)
    first = p.db.add_task("first", "s", kind="work", status="running")
    second = p.db.add_task("second", "s", kind="work", status="running")
    out = coord.apply(p, [{"type": "task_add", "title": "after", "spec": "s", "start_when": f"landed:#{first}",
                           "why": "first's change is in"}])
    after = p.db.one("SELECT * FROM tasks WHERE title='after'")
    notes = p.db.kv(coord.NOTES_KEY)
    assert out == [] and after and dependency_ids(after) == [first] and not deferral(after), (out, after)
    assert [n for n in notes if f"task_add: #{after['id']} added; start_when landed:#{first} became depends_on "
            f"[{first}]: " in n and "delivery.landed_probe" in n and f"once #{first} is done" in n], notes
    other = p.db.add_task("other", "s", kind="work", status="queued", depends_on=[second])
    out = coord.apply(p, [{"type": "task_update", "id": other, "start_when": f" landed: {first} "}])
    notes = p.db.kv(coord.NOTES_KEY)
    assert out == [] and dependency_ids(p.db.task(other)) == [second, first] and not deferral(p.db.task(other)), out
    assert [n for n in notes if n.startswith(f"task_update: #{other} start_when landed: {first} became "
                                             f"depends_on [{first}]: ")], notes
    # ANDed with the other terms: those stay the start_when; a depends_on sent along is the base.
    out = coord.apply(p, [{"type": "task_update", "id": other, "depends_on": [second],
                           "start_when": f"test -e out/x && ttp landed --task {first} && ttp landed '#{second}'"}])
    assert out == [] and dependency_ids(p.db.task(other)) == [second, first], out
    assert deferral(p.db.task(other))["when"] == "test -e out/x", out
    assert [n for n in p.db.kv(coord.NOTES_KEY) if f"depends_on [{first}, {second}]; start_when test -e out/x: "
            in n], p.db.kv(coord.NOTES_KEY)
    out = coord.apply(p, [{"type": "task_add", "title": "either", "spec": "s",
                           "start_when": f"ttp landed --task {first} || test -e out/y"}])
    either = p.db.one("SELECT * FROM tasks WHERE title='either'")
    assert out == [] and dependency_ids(either) == [] and deferral(either)["when"].startswith("ttp landed"), out
    with pytest.raises(SystemExit):
        cli.main(["task", "demo", "add", "cli later", "--start-when", f"landed:#{first}"])
    seen = capsys.readouterr()
    assert "delivery.landed_probe" in seen.out + seen.err, seen
    assert not p.db.one("SELECT id FROM tasks WHERE title='cli later'")
    with pytest.raises(ValueError, match="delivery.landed_probe"):
        cli.set_when(p.db, other, f"landed:#{first}", p)
    for key, value in (("delivery.landed_probe", "test -e landed/{id}"), ("delivery.push_branch", "tt/push")):
        p.set_config("delivery.landed_probe", "")
        p.set_config(key, value)
        assert coord.apply(p, [{"type": "task_update", "id": other, "depends_on": [],
                                "start_when": f"landed:#{first}"}]) == []
        assert deferral(p.db.task(other))["when"] == f"landed:#{first}" and dependency_ids(p.db.task(other)) == []
        coord.apply(p, [{"type": "task_update", "id": other, "start_when": "now"}])


def test_the_audit_json_has_a_repeated_instructions_row_matching_the_text_clause(env):
    from ttp import audit, correction
    p = make(env)
    now = time.time()
    assert audit.report(p.db, now)["repeated_instructions"] == {"count": 0, "top_sentence": "", "top_count": 0, "first_id": None}
    first = _said(p, "Run the full suite before pushing.", days=3)
    a = _said(p, "run the full suite before pushing please", days=0.5)
    b = _said(p, "Again: run the full suite before pushing.")
    p.db.set_kv(correction.KEY, [
        {"msg": a, "ts": now - 3600, "why": f"repeats #{first}", "fix": "", "shown": True},
        {"msg": b, "ts": now - 60, "why": f"repeats #{first}", "fix": "", "shown": False}])
    assert audit.report(p.db, now)["repeated_instructions"] == {
        "count": 2, "top_sentence": "run the full suite before pushing", "top_count": 2, "first_id": first}


def test_promise_filler_accepts_hash_and_parenthesised_numbers():
    """'#812' and '(812)' are filler tokens like '812'; a sentence end still stops the match."""
    from ttp import obligations as ob
    for text in ("I'll post the #812 table here.", "I'll post the #812 results here.",
                 "I'll post the (812) table here.", "I'll post the (812) results here."):
        assert ob.commitments(text) == [text], text
    for text in ("I posted the #812 table here.", "If you want, I'll post the (812) table here.",
                 "I'll check it. The #812 table is here."):
        assert ob.commitments(text) == [], text


def test_mute_slots_show_near_the_cap_and_only_mutes_in_force_hold_one(env):
    """A turn that cannot see how many mute slots are left sends a mute the cap refuses: near the cap
    the digest counts them and names the mute that ends first. A mute past its end no longer holds a
    slot, so the cap refuses only what the digest shows as full."""
    from ttp import coordinator as coord, screen as scr
    p = make(env)
    db, now = p.db, time.time()
    for i in range(scr.MUTE_MAX - scr.MUTE_SLOTS_NEAR - 1):
        scr.mute(db, f"watcher:w{i}", f"condition number {i}", 2 + i, why="known noise", now=now)
    far = next(x for x in coord.digest(p, {}, [], []).splitlines() if x.startswith("## Muted observations"))
    assert f"; {scr.MUTE_SLOTS_NEAR + 1} of {scr.MUTE_MAX} mute slots free)" in far and "first to end" not in far, far
    scr.mute(db, "watcher:w99", "condition number 99", 1, why="known noise", now=now)
    shown = coord.digest(p, {}, [], [])
    line = next(x for x in shown.splitlines() if x.startswith("## Muted observations"))
    assert f"; {scr.MUTE_SLOTS_NEAR} of {scr.MUTE_MAX} mute slots free, first to end: watcher:w99 " \
           f"'condition number 99' in 1.0 h)" in line, line
    seen = coord.digest_parts(p, {}, [], [], {}, {})[1]
    again = dict(coord.digest_parts(p, {}, [], [], seen, {})[0])["muted"]
    assert "(as last turn; never wake you; 5 of 20 mute slots free" in again, again
    for i in range(scr.MUTE_MAX - scr.MUTE_SLOTS_NEAR, scr.MUTE_MAX):
        scr.mute(db, f"watcher:x{i}", f"condition number {i}", 3, why="known noise", now=now)
    with pytest.raises(ValueError, match=f"observation_mute rejected: {scr.MUTE_MAX} mutes are already active; "
                                         f"let one end first$"):
        scr.mute(db, "watcher:new", "another condition", 2, now=now)   # the cap itself still holds
    later = now + 3601   # watcher:w99 ended, not yet swept from the list
    assert len(db.kv(scr.MUTES_KEY)) == scr.MUTE_MAX and len(scr.mutes(db, later)) == scr.MUTE_MAX - 1
    assert scr.mute(db, "watcher:new", "another condition", 2, now=later)["source"] == "watcher:new"


def test_obligation_actions_on_a_delivered_obligation_are_noted_not_rejected(env, monkeypatch):
    """Attaching the task that delivered it, adding a milestone, dropping it or recording its receipt
    again, once an obligation has its receipt, changes nothing owed: a note, not a rejection."""
    from ttp import coordinator as coord
    from ttp import obligations as ob
    p, d, now, tid, check = _ob_setup(env, monkeypatch)
    oid = ob.add(p, "the urgent report", [tid], now=now)
    ob.record(p, oid, "receipt", "docs/report.md", None, now=now)
    p.db.update_task(tid, status="done")
    before = ob.get(p.db, oid)
    for a in ({"owners": [tid]}, {"milestones": [{"key": "m1", "due": "2030-01-01T00:00:00+00:00",
                                                  "evidence_required": "a file"}]},
              {"why": "delivered"}, {"evidence": "docs/report.md again"}):
        assert coord.apply(p, [{"type": "obligation", "key": oid, **a}]) == [], a
        assert "receipt" in " ".join(p.db.kv(coord.NOTES_KEY) or []), a
    assert ob.get(p.db, oid) == before, "nothing changed"
    assert coord.effort_triggers(p.db, p.config(), [], None)[0] == []
    # Still refused: an obligation that is owed cannot take a finished task as its producer.
    owed = ob.add(p, "another report", now=now)
    out = coord.apply(p, [{"type": "obligation", "key": owed, "owners": [tid]}])
    assert len(out) == 1 and "attach the task that will produce it" in out[0]
    assert not coord.informational_rejection(out[0])


def test_information_only_refusals_ride_along_and_real_rules_still_raise_a_turn(env):
    """A refusal that only reports open or landed work, or a field a running task keeps, reaches the
    next digest without raising a turn by itself; one that needs a decision still raises it."""
    from ttp import coordinator as coord
    p = make(env)
    db, cfg = p.db, p.config()
    trig = lambda: coord.effort_triggers(db, cfg, [], None)[0]
    run = db.add_task("running work", "spec", kind="code", origin="user")
    db.update_task(run, status="running")
    open_ = db.add_task("open work", "spec", origin="user")
    landed = db.add_task("compact the cache to 4 MB", "Compact the cache to 4 MB.", kind="code", origin="user")
    db.update_task(landed, status="done", attempts=1,
                   result=json.dumps({"status": "done", "summary": "Kept: the cache is 4 MB."}))
    db.x("INSERT INTO task_landings(marker, task, sha, target) VALUES('m1', ?, 'abc1234', 'work')", (landed,))
    shelved = db.add_task("fuse the norm (bound 1.8x)", "Fuse the norm; bound 1.8x.", kind="code", origin="user")
    db.update_task(shelved, status="done", attempts=1,
                   result=json.dumps({"status": "done", "summary": "Shelved: 1.05x of the 1.8x bound."}))
    info = [{"type": "task_update", "id": run, "resources": ["m1"]},
            {"type": "task_update", "id": run, "pr_branch": "feature/x"},
            {"type": "task_update", "id": run, "model": "other"},
            {"type": "task_update", "id": run, "status": "queued"},
            {"type": "task_update", "id": run, "start_after": "+1h"},
            {"type": "task_add", "title": "open work", "spec": "spec"},
            {"type": "task_add", "title": "Compact the cache to 4 MB", "kind": "code", "spec": "Compact it to 4 MB."}]
    for a in info:
        out = coord.apply(p, [a])
        assert len(out) == 1 and coord.informational_rejection(out[0]), (a, out)
        db.set_kv(coord.REJECTED_KEY, out)
        assert trig() == [], (a, out)
        shown = coord.digest(p, {}, [], [])
        assert "refused, information only: nothing to fix" in shown and coord.INFO_MARK not in shown
    assert f"ledger entry #{landed}: task done, closed, landed" in out[0], out[0]
    assert db.task(run)["status"] == "running" and json.loads(db.task(run)["labels"] or "[]") == []
    assert db.one("SELECT COUNT(*) n FROM tasks")["n"] == 4, "refused exactly as before: nothing added"
    # Refusals for a rule or a decision still raise the next turn, worded as before; so does work
    # already tried when a reply in the same batch may rest on it (settle_refusals).
    decide = [[{"type": "task_add", "title": "Fuse the norm, bound 1.8x", "kind": "code", "spec": "Fuse it; 1.8x."},
               {"type": "reply", "chat": "c1", "text": "Queued the norm fusion."}],
              {"type": "pr_approve", "id": 999999, "text": "https://github.com/acme/widgets/pull/7", "quote": "yes"},
              {"type": "task_update", "id": 999999, "priority": 1}]
    for a in decide:
        out = coord.apply(p, a if isinstance(a, list) else [a])
        assert len(out) == 1 and not coord.informational_rejection(out[0]), (a, out)
        db.set_kv(coord.REJECTED_KEY, out)
        assert trig() == ["rejected action"], (a, out)
        assert "your previous turn's action was rejected; fix or drop it" in coord.digest(p, {}, [], [])
    assert "was shelved" in coord.apply(p, decide[0])[0] and \
        f"ledger entry #{shelved}: task done, closed, not landed" in coord.apply(p, decide[0])[0]


def test_settled_refusals_cost_no_turn_of_their_own_and_show_once_with_a_count(env, monkeypatch):
    """Work already tried and a mute with no free slot are refused the same way on every turn: alone in
    a batch they raise no turn of their own (the quiet gate still settles the next routine batch) and
    reach the next naturally started turn's digest, once each with its count. With a reply in the same
    batch, or for any other refusal, the next routine batch runs as before."""
    p = make(env)
    from types import SimpleNamespace
    from ttp import coordinator as coord, quietgate, screen as scr
    from ttp.daemon import Daemon
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    held = p.db.add_task("tuning", "s", origin="user")
    p.db.update_task(held, status="blocked", blocked_reason="paused by the user",
                     labels=["waits:when:test -e state/user-resume-tuning || exit 1"])
    shelved = p.db.add_task("fuse the norm (bound 1.8x)", "Fuse the norm; bound 1.8x.", kind="code", origin="user")
    p.db.update_task(shelved, status="done", attempts=1,
                     result=json.dumps({"status": "done", "summary": "Shelved: 1.05x of the 1.8x bound."}))
    d = Daemon(p.base)
    d.update_gates()
    d.cfg["coordinator"].update(skip_repeat_window_s=0, batch_s=0)
    clock = [time.time()]
    prompts, notes = [], []

    def start_run(role, prompt, *a, **k):
        prompts.append(prompt)
        notes.append(k["note"])
        return p.db.x("INSERT INTO runs(role,started,status,note) VALUES('coordinator',?,'ok',?)",
                      (clock[0], json.dumps(k["note"])))
    monkeypatch.setattr(d, "start_run", start_run)
    monkeypatch.setattr(time, "time", lambda: clock[0])

    def event(actions=({"type": "noop"},), kind="idle_capacity"):
        clock[0] += 600
        p.db.x("INSERT INTO events(ts,source,kind,severity,text,status) VALUES(?,?,?,?,?,?)",
               (clock[0], "daemon", kind, "normal", f"{kind}:board-b:{int(clock[0])}", "queued"))
        clock[0] += 60
        n = len(prompts)
        d.maybe_coordinate()
        if len(prompts) == n:
            return False
        rid = p.db.one("SELECT MAX(id) id FROM runs")["id"]
        usage = SimpleNamespace(structured={"actions": list(actions), "summary": ""}, error="", final_text="",
                                cost_usd=0.2)
        d._finish_coordinator({"id": rid, "dir": "x"}, usage, "ok", notes[-1])
        return True

    tried = {"type": "task_add", "title": "Fuse the norm, bound 1.8x", "kind": "code", "spec": "Fuse it; 1.8x."}
    assert event([tried, tried]), "the first batch runs: no turn has left its state yet"
    assert len(p.db.kv(coord.REJECTED_KEY)) == 2
    assert coord.effort_triggers(p.db, d.cfg, [], None)[0] == []
    assert not event(), "a batch refused only as already tried raises no turn of its own"
    assert event(kind="task_note"), "a natural turn still runs"
    shown = [x for x in prompts[-1].splitlines() if f"already tried: task #{shelved}" in x]
    assert len(shown) == 1 and "refused, information only: nothing to fix; sent 2 times]" in shown[0], shown
    assert not event()
    # No free mute slot.
    now = clock[0]
    for i in range(scr.MUTE_MAX):
        scr.mute(p.db, f"watcher:w{i}", f"condition number {i}", 3, why="known noise", now=now)
    mute = {"type": "observation_mute", "source": "watcher:new", "match": "another condition", "hours": 2}
    assert event([mute], kind="task_note")
    assert f"; no mute slot free (all {scr.MUTE_MAX} used), first to end: " in prompts[-1]
    assert coord.informational_rejection(p.db.kv(coord.REJECTED_KEY)[0])
    assert not event(), "a batch refused only for want of a mute slot raises no turn of its own"
    assert event(kind="task_note")
    assert f"observation_mute rejected: {scr.MUTE_MAX} mutes are already active" in prompts[-1]
    assert not event()
    # A reply in the same batch may rest on the refused task: the next batch runs, as before.
    assert event([tried, {"type": "reply", "chat": "web", "text": "Queued the norm fusion."}], kind="task_note")
    assert not coord.informational_rejection(p.db.kv(coord.REJECTED_KEY)[0])
    assert event(), "a refusal a reply may rest on raises the next turn"
    assert not event()
    # Another refusal class keeps raising the next turn.
    assert event([{"type": "task_update", "id": 999999, "priority": 1}], kind="task_note")
    assert event(), "a refusal that needs a decision raises the next turn"
    assert not event()
    assert quietgate.skipped(p.db, 0)["n"] == 6


def test_settle_refusals_marks_only_its_classes_and_only_without_a_backing_action():
    from ttp import coordinator as coord
    settled = ["task_add: already tried: task #3 'x'", "task_add: near duplicate of task #4 (done) 'y'",
               "observation_mute: observation_mute rejected: 20 mutes are already active; let one end first",
               "observation_mute: observation_mute rejected: watcher:w 'z' has been muted for 7 days, the most"]
    other = ["task_update: #9 rejected: already tried: x", "task_add: cap of 3 new tasks in 24 h reached",
             "observation_mute: observation_mute needs `hours` from 1 to 72", "ask_user: already tried: x"]
    out = coord.settle_refusals(settled + other, [{"type": "task_add"}, {"type": "observation_mute"}])
    assert [coord.informational_rejection(x) for x in out] == [True] * 4 + [False] * 4, out
    assert coord.settle_refusals(out, []) == out, "an information-only refusal is marked once"
    for backing in coord.BACKING_ACTIONS:
        assert coord.settle_refusals(settled, [{"type": "task_add"}, {"type": backing}]) == settled, backing
    assert coord.settle_refusals(settled, [None, "noise"])[0].endswith(coord.INFO_MARK)


def test_a_clipped_information_only_refusal_keeps_its_mark():
    from ttp import coordinator as coord
    long = "task_add: already tried: " + "x" * 900 + f" {coord.INFO_MARK}"
    cut = coord.clip_rejection(long)
    assert coord.informational_rejection(cut) and len(cut) <= 500 + len(coord.INFO_MARK) + 1
    assert coord.clip_rejection("task_update: no task " + "y" * 900) == ("task_update: no task " + "y" * 900)[:500]


def _fill_worker_room(p, short: int):
    """Entries for workers that leave `short` chars of the room worker prompts give pinned memory."""
    from ttp.prompts import worker_context
    room = worker_context(p)[2]["memory_limit"]
    paths, used = [], 0
    while room - used - short > 0:
        n = min(900, room - used - short - 14)
        if n < 30:
            break
        path = p.add_memory("RULE " + "r" * n, kind="decision", title=f"rule {len(paths)}", audience="workers")
        paths.append(path)
        used = worker_context(p)[2]["pinned_chars"]
    assert 0 < room - used <= short + 60, (room, used)
    return paths


def test_memory_cli_warns_once_a_new_entry_workers_see_overflows_their_pinned_room_and_reroutes_one_offs(env, capsys):
    """`ttp memory` adding an entry workers see warns once it takes the memory pinned for workers past
    the room worker_context gives it, naming that room, the new total and the largest entries workers
    see. A one-off decision or fact with no --audience is then stored for the coordinator alone; an
    explicit audience (workers or default), a standing entry and other kinds are kept and only warned
    about. Under the room: no warning and no re-route."""
    p = make(env)
    from ttp import cli
    from ttp.prompts import worker_context
    _fill_worker_room(p, 400)
    room = worker_context(p)[2]["memory_limit"]
    capsys.readouterr()

    def add(text, *argv):
        cli.main(["memory", "demo", text, *argv])
        out = capsys.readouterr()
        e = p._memory_entries()[-1]
        assert e["body"] == text, e
        return e, out.err

    # (e) Under the room: stored as given, no warning.
    e, err = add("Workers run the short suite first.", "--kind", "fact")
    assert e["audience"] == "" and "warning" not in err, err
    e, err = add("Workers keep the lock for one command.", "--kind", "decision", "--audience", "workers")
    assert e["audience"] == "workers" and "warning" not in err, err
    big = "Workers note: " + "w" * 600
    # (a) + (c) A one-off fact or decision with no audience past the room: warned and re-routed.
    for kind in ("fact", "decision"):
        e, err = add(f"{big} {kind}", "--kind", kind)
        assert e["audience"] == "coordinator" and e["kind"] == kind, e
        total = worker_context(p)[2]["pinned_chars"] + len(e["line"]) + 1
        assert f"warning: pinned worker memory would take {total} chars with [{e['name']}] " in err, err
        assert f"over the {room} chars of room worker prompts leave it; largest entries workers see: decision-rule-" in err
        assert "stored for the coordinator only (audience coordinator)" in err, err
    # (d) An explicit audience is kept and only warned about.
    for aud, stored in (("workers", "workers"), ("default", "")):
        before = worker_context(p)[2]["pinned_chars"]
        e, err = add(f"{big} {aud}", "--kind", "fact", "--audience", aud)
        assert e["audience"] == stored, e
        assert "warning: pinned worker memory would take " in err and "stored as given" in err, err
        assert "coordinator only" not in err
        if aud == "workers":
            assert f"would take {before + len(e['line']) + 1} chars" in err, err
    # (f) A standing entry and other kinds are never re-routed.
    for argv in (("--kind", "fact", "--standing"), ("--kind", "decision", "--standing"), ("--kind", "resource"),
                 ("--kind", "preference", "--standing")):
        e, err = add(f"{big} {' '.join(argv)}", *argv)
        assert e["audience"] == "" and "stored as given" in err, (argv, e, err)
    # Meant for the coordinator alone: workers never see it, so no warning.
    e, err = add(f"{big} coordinator", "--kind", "decision", "--audience", "coordinator")
    assert e["audience"] == "coordinator" and "would take" not in err, err
    # A dry run warns and re-routes on paper only.
    n = len(p._memory_entries())
    cli.main(["memory", "demo", f"{big} dry", "--kind", "fact", "--dry-run"])
    err = capsys.readouterr().err
    assert "dry run, nothing written or committed: warning: pinned worker memory would take " in err, err
    assert len(p._memory_entries()) == n


def test_memory_add_action_notes_a_worker_room_overflow_and_reroutes_a_one_off(env):
    """The coordinator's memory_add gets the same check: past the room, a note on its action names the
    room, the new total and the largest entries workers see; a one-off fact with no audience is stored
    for the coordinator alone, an explicit one kept. Under the room, no note. A merge (`supersedes`)
    is warned about once the replaced entries are gone, and never re-routed."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp.prompts import worker_context
    rules = _fill_worker_room(p, 400)
    room = worker_context(p)[2]["memory_limit"]

    def apply(action, turn):
        assert coord.apply(p, [dict(action, type="memory_add")], turn=turn) == []
        return p.db.kv(coord.NOTES_KEY)
    assert apply({"text": "Workers run the short suite first.", "memory_kind": "fact"}, 1) == []
    assert p._memory_entries()[-1]["audience"] == ""
    big = "Workers note: " + "w" * 600
    notes = apply({"text": big, "memory_kind": "fact"}, 2)
    e = p._memory_entries()[-1]
    assert e["audience"] == "coordinator", e
    assert len(notes) == 1 and notes[0].startswith(
        f"memory_add: warning: pinned worker memory would take "), notes
    assert f"with [{e['name']}] " in notes[0] and f"over the {room} chars of room" in notes[0]
    assert "largest entries workers see: decision-rule-" in notes[0] and "stored for the coordinator only" in notes[0]
    # The same turn replayed keeps its one entry and its audience.
    assert apply({"text": big, "memory_kind": "fact"}, 2) == notes
    assert [x["audience"] for x in p._memory_entries() if x["body"] == big] == ["coordinator"]
    notes = apply({"text": big + " kept", "memory_kind": "fact", "audience": "workers"}, 3)
    assert p._memory_entries()[-1]["audience"] == "workers"
    assert len(notes) == 1 and "stored as given" in notes[0], notes
    notes = apply({"text": big + " merged", "memory_kind": "decision", "supersedes": [rules[0].stem]}, 4)
    e = p._memory_entries()[-1]
    assert e["audience"] == "" and not (p.memory_dir / f"{rules[0].stem}.md").exists()
    assert len(notes) == 1 and notes[0].startswith("memory_add: warning: pinned worker memory would take "), notes
